/* Measurement: runs the transcript scan, keeps readings and plan history in $.store keyed
   by subscription, and turns them into estimates. The engine reaches this module through
   a Host that register.tsx builds, since $ itself never crosses an import. After a measure,
   a second helper call rebuilds the per-feature dollars of readings stored without them,
   and the meter-weight model fit is refreshed; the estimates do not use it.

   $.store is one store shared by every running session, so each key is read immediately
   before it is written, with no wait on the helper in between, and the plan, regime,
   promotion and notice keys are written only when they changed. */

import type { SessionRateLimit } from 'claude-code'

import type {
  CalibrationReport,
  CheckItem,
  CheckReport,
  ModelSpend,
  ModelsFit,
  ModelsReport,
  PlanReport,
  SpendReport,
  UsageReport,
  WindowReport,
} from '../types'
import { money, statusLine } from './card'
import {
  MIN_ROUNDING_WINDOWS,
  calibrateOmega,
  calibrationOf,
  estimate,
  pastPoints,
  prior,
  record,
  regimeView,
  resolutionOf,
  roundingEvidence,
  tQuantile,
} from './estimate'
import type { Calibration, Estimate, Rounding, WindowReadings } from './estimate'
import { UNIT_WEIGHTS, fingerprintOf, isFeatureComplete, prospectiveScore, selectModel, transferCheck, weightedView } from './meter'
import type { FitResult, ProspectiveRecord, Selection, StoredFit, Transfer } from './meter'
import { activePromotions, addRegimes, currentRegime, observePlan, observePromotions, planLabel, regimeStart, startOver, undoStartOver } from './plan'
import type { Kind, Ledger, NoticeDraft, PlanEntry, Profile, Promotions, Regime, Regimes } from './plan'

const MINUTE_MS = 60 * 1000
const HOUR_MS = 60 * MINUTE_MS
const DAY_MS = 24 * HOUR_MS
const MIN_GAP_MS = MINUTE_MS
const FRESH_MS = 5 * MINUTE_MS
const READINGS_KEPT_MS = 28 * DAY_MS
const HISTORY_DAYS = 14
const HISTORY_REFRESH_MS = 6 * HOUR_MS
const NOTICE_SHOWN_MS = 7 * DAY_MS
const STALE_PROFILE_MS = 7 * DAY_MS
const KEPT_NOTICES = 20
/* Above this share of a window's requests going to unpriced models, its dollars no longer
   track the limit. */
const MAX_UNPRICED_SHARE = 0.02
const SCHEMA = 5
/* What the limits and readings this module stores mean; raise it whenever that changes.
   A stored limit without one is stamp 0. */
const HOOKS_STAMP = 2
/* The engine rejects a store over 4 MiB of JSON text in all keys together; the readings
   stay within 3 MiB and the other keys are small. */
const MAX_READINGS_CHARS = 3 * 1024 * 1024
/* The backfill: window specs per helper call, and its timeout. */
const BACKFILL_MAX_SPECS = 100
const BACKFILL_TIMEOUT_MS = 120_000
/* A side's backfilled dollars match its stored ones within max(relative · usd, absolute),
   the tolerance of a feature-complete window in meter.ts. */
const FEATURE_TOLERANCE_RELATIVE = 1e-6
const FEATURE_TOLERANCE_ABSOLUTE = 2e-4
/* Per-feature dollars are stored in units of 1e-6, as record() stores them. */
const X_UNIT = 1e6
/* Qualifying 5-hour windows a model fit needs, as in meter.ts. */
const FIT_MIN_WINDOWS = 4
/* ω of a stored fit without a fitted model; unused, since its weights are M0's. */
const UNFITTED_OMEGA = 0.5
/* Prospective records kept per subscription. */
const PROSPECTIVE_KEPT = 100
const NONE = 'none'
/* The suffixes of a window's further tallies: up to the moment this session received its
   percent, and up to the moment the stored percent was received. */
const AT_READ = '@read'
const AT_STORED = '@stored'
/* Median ratio of these dollars to Claude Code's own costs outside which the price table
   is out of date. */
const MIN_PRICE_RATIO = 0.9
const MAX_PRICE_RATIO = 1.1

const SCHEMA_KEY = 'schema'
const LIMITS_KEY = 'limits'
const READINGS_KEY = 'readings'
const HISTORY_KEY = 'history'
const PLANS_KEY = 'plans'
const REGIMES_KEY = 'regimes'
const PROMOTIONS_KEY = 'promotions'
const NOTICES_KEY = 'notices'
const METER_KEY = 'meter'

export const INFERRED_TEXT =
  'Usage no longer matches recent windows: limits may have changed, or this subscription was used elsewhere ' +
  '(inferred from usage, not from the plan). If you changed plans, run /usage-dollars reset.'

const WINDOWS: readonly { kind: Kind; name: string; title: string; short: string; spanMs: number }[] = [
  { kind: 'five_hour', name: 'session', title: '5-hour window', short: '5h', spanMs: 5 * HOUR_MS },
  { kind: 'seven_day', name: 'week', title: 'This week', short: 'Week', spanMs: 7 * DAY_MS },
]

const SPAN_MS: Record<string, number> = { five_hour: 5 * HOUR_MS, seven_day: 7 * DAY_MS }

const KINDS: readonly Kind[] = ['five_hour', 'seven_day']

const KIND_TITLES: Record<Kind, string> = { five_hour: '5-hour windows', seven_day: 'Weeks' }

/** What this module needs from the engine: the clock, the session, the helper process,
    $.store, the status line and the debug log. */
export type Host = {
  root: string
  now: () => Promise<number>
  sessionId: () => Promise<string>
  rateLimits: () => Promise<readonly SessionRateLimit[]>
  run: (argv: string[], options: { timeoutMs: number }) => Promise<{ stdout: string; stderr: string; exitCode: number | null }>
  get: (key: string) => Promise<unknown>
  set: (key: string, value: unknown) => Promise<void>
  delete: (key: string) => Promise<void>
  status: (text: string) => void
  log: (text: string) => void
}

type OrgSource = 'session' | 'profile' | 'most recent'

/* observedAt: when a session last received this percent from the API; absent for a reset
   rolled forward without one. */
type Limit = { percentUsed?: number; resetsAt: string; observedAt?: number }

/* sessionId: the session that received the percent; stamp: its HOOKS_STAMP. */
type StoredLimit = { percentUsed?: number; resetsAt: string; observedAt: number; sessionId?: string; stamp?: number }

type StoredLimits = Record<string, Record<string, StoredLimit>>

/* featuresUnverified: the backfill could not rebuild the window's per-feature dollars, and
   does not try again. */
type StoredReading = WindowReadings & { org: string; featuresUnverified?: boolean }

type StoredReadings = Record<string, StoredReading>

/* The model fit of one subscription, refitted only when its fingerprint changes.
   included: the keys of the qualifying closed windows per kind; regimeStarts: per kind;
   rounding: the rule of the second pass; fits: per kind, the weights in use with their ω
   and M0's; prospective: new windows scored before each refit, the latest kept. */
type MeterEntry = {
  fingerprint: string
  included: Record<string, string[]>
  regimeStarts: Record<string, number>
  pricesId?: string
  rounding: Rounding
  selection: Selection
  transfer: Transfer
  fits: Record<string, StoredFit>
  prospective: ProspectiveRecord[]
}

type StoredMeter = Record<string, MeterEntry>

/* The subscription and price table whose readings a measure wrote. */
type MeterContext = { subscription: string; pricesId?: string }

type Observation = { kind: string; resetsAt: string; at: string; usd: number }

type History = Record<string, { scannedAt: number; observations: Observation[] }>

export type Notice = {
  id: string
  kind: NoticeDraft['kind']
  org: string
  text: string
  at: number
  isToasted: boolean
  isSeen: boolean
}

type WindowTally = {
  usd: number
  requests: number
  byModel: Record<string, { usd: number; requests: number }>
  /* usd by feature `<priceKey>[+fast]/<class>` or `web`; keys above 0 only. */
  byFeature?: Record<string, number>
  otherSubscriptionsUsd: number
  unattributedUsd: number
  unpricedRequests: number
  unpricedModels: string[]
  /* Other sessions' dollars just before the tally's end, which its percent may lack. */
  slackUsd?: number
  resetLabel?: string
  resetLong?: string
  resetIn?: string
}

type HelperBase = {
  org?: string | null
  orgSource?: OrgSource | null
  profile?: Profile | null
  labels?: Record<string, string>
  error?: string
}

type WindowsOutput = HelperBase & { windows?: Record<string, WindowTally>; pricesId?: string; files: number; ms: number }

type ReportOutput = HelperBase & {
  usd: number
  requests: number
  byModel: Record<string, { usd: number; requests: number }>
  byDay: { date: string; label: string; usd: number; requests: number }[]
  otherSubscriptionsUsd: number
  unattributedUsd: number
  unpricedRequests: number
  unpricedModels: string[]
  fromLabel: string
  toLabel: string
  transcriptsBeginLabel?: string
}

/* closedWindows: closed windows of this kind and regime that hold readings. halfWidth: of
   the current 90% range, in proportion. */
type WindowCalibration = Calibration & { closedWindows: number; rounding: Rounding; halfWidth?: number }

type WindowState = {
  title: string
  short: string
  resetsAt: string
  tally: WindowTally
  estimate?: Estimate
  isUnpriced: boolean
  sinceResetLabel?: string
  percent?: number
  percentAt?: number
  calibration: WindowCalibration
}

/* Why a percent a measure could have recorded was not: `missing` when nothing explains it. */
type Outcome = 'recorded' | 'unpriced' | 'unattributed' | 'missing'

/* A percent that may be recorded: this session's fresh one, or one stored by a session
   whose reading of it may have been lost. sessionId: the session that received it. */
type Candidate = { source: 'mine' | 'stored'; tally: string; percent: number; at: number; sessionId: string }

/* A candidate a measure tried to record, under the window key, and what became of it. */
type Attempt = { title: string; key: string; c: Candidate; outcome?: Outcome }

export type Diagnostics = {
  /* Another session stored a percent with other hooks since this module first measured:
     older or newer than this one's. */
  otherHooks?: 'older' | 'newer'
  /* Stored windows dropped for another price table, over this session's measures. */
  droppedForPrices: number
  /* Closed windows dropped to keep the readings within MAX_READINGS_CHARS. */
  droppedForSize: number
  /* Per window title, what became of the percents the latest measure that had any could
     record. */
  outcomes: Record<string, { source: Candidate['source']; outcome: Outcome }[]>
}

export type Summary = {
  subscription: string
  orgSource?: OrgSource | null
  windows: WindowState[]
  plan: PlanReport
  notices: string[]
  last24hUsd?: number
  /* The last 7 days' dollars by feature. */
  last7dX?: Record<string, number>
  sinceResetLabel?: string
  files: number
  ms: number
}

/* The session's subscription, once a helper run attributed it through the session's own
   record; until then each measure asks the helper first. */
let sessionOrg: string | undefined
let lastSubscription: string | undefined
let isMigrated = false
let last: Summary | undefined
let lastRunAt = 0
let running: Promise<Summary | undefined> | undefined
/* When this session last received its percents; their age decides between them and the
   ones other sessions stored. */
let lastFreshAt: number | undefined
/* A fresh measure that arrived while another ran, with the time its percents arrived;
   the latest wins. */
let pendingFresh: { host: Host; limits?: readonly SessionRateLimit[]; receivedAt?: number } | undefined
let firstMeasureAt: number | undefined
const diagnostics: Diagnostics = { droppedForPrices: 0, droppedForSize: 0, outcomes: {} }
/* The latest measure that wrote readings; the backfill and the model fit follow it. */
let meterContext: MeterContext | undefined
/* The backfill and model fit in flight, and the measure queued after it; the latest wins. */
let followUp: Promise<void> | undefined
let queuedFollowUp: { host: Host; context: MeterContext } | undefined
/* Every write of the readings from this module, one at a time. */
let readingsTurn: Promise<unknown> = Promise.resolve()

const subscriptionOf = (org: string | null | undefined) => org ?? NONE

const isSame = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

const windowKey = (subscription: string, kind: string, resetsAt: string) =>
  `${subscription}|${kind}@${new Date(Math.round(Date.parse(resetsAt) / MINUTE_MS) * MINUTE_MS).toISOString()}`

const helperArgv = (host: Host) => ['node', `${host.root}/scripts/usage-cost.mjs`]

async function runHelper<T extends HelperBase>(host: Host, extra: readonly string[], timeoutMs: number) {
  return runScript<T>(host, ['--session', await host.sessionId(), ...extra], timeoutMs)
}

async function runScript<T extends { error?: string }>(host: Host, extra: readonly string[], timeoutMs: number) {
  const run = await host.run([...helperArgv(host), ...extra], { timeoutMs })
  let out: T | undefined
  try {
    out = JSON.parse(run.stdout || '{}') as T
  } catch {
    out = undefined
  }
  if (run.exitCode !== 0 || !out || out.error) {
    const error = out?.error ?? run.stderr.slice(0, 200)
    return { error: error || `helper exited with ${run.exitCode}` }
  }
  return { out }
}

/* v0.3.0 kept limits, readings and history without a subscription; they cannot be
   attributed, so they are dropped once and the estimates start again.
   Before schema 3 any session paired its own last percent, however old, with the dollars
   of the moment and stored the pair; nothing tells those readings or limits from sound
   ones, so both are dropped once more. Schema-3 readings paired the percent with the
   dollars at the time of the scan and carry no slack or price table, so they are dropped
   once again. History comes from rate-limit rejections in the transcripts, not from
   percents, and is kept from schema 2 on. Schema-4 limits and readings lack only the
   per-feature dollars, which the backfill rebuilds, so they are kept. */
async function migrate(host: Host) {
  if (isMigrated) return
  const was = await host.get(SCHEMA_KEY)
  if (was !== SCHEMA) {
    if (was !== 4) {
      await host.delete(LIMITS_KEY)
      await host.delete(READINGS_KEY)
      if (was !== 2 && was !== 3) await host.delete(HISTORY_KEY)
    }
    await host.set(SCHEMA_KEY, SCHEMA)
  }
  isMigrated = true
}

/* Runs `work`, which reads the readings and writes them, after every such work of this
   module started before it. */
function exclusively<T>(work: () => Promise<T>): Promise<T> {
  const turn = readingsTurn.then(work)
  readingsTurn = turn.catch(() => undefined)
  return turn
}

/* The readings within MAX_READINGS_CHARS of JSON text: the oldest closed windows give way
   first, each one counted. */
function withinSize(readings: StoredReadings, now: number): StoredReadings {
  let size = JSON.stringify(readings).length
  if (size <= MAX_READINGS_CHARS) return readings
  const kept = { ...readings }
  const oldest = Object.entries(kept)
    .filter(([, r]) => Date.parse(r.resetsAt) <= now)
    .sort(([, a], [, b]) => Date.parse(a.resetsAt) - Date.parse(b.resetsAt))
  for (const [key, r] of oldest) {
    if (size <= MAX_READINGS_CHARS) break
    size -= JSON.stringify(key).length + JSON.stringify(r).length + 2
    delete kept[key]
    diagnostics.droppedForSize++
  }
  return kept
}

/** The session's subscription key: its own record, else the signed-in one, else "none". */
export async function resolveSubscription(host: Host) {
  await migrate(host)
  if (sessionOrg) return sessionOrg
  const { out } = await runHelper<HelperBase>(host, ['--whoami'], 30_000)
  if (out?.orgSource === 'session' && out.org) sessionOrg = out.org
  return subscriptionOf(out?.org)
}

/* The limit as last stored for the subscription: a 7-day window rolls forward a week at a
   time, without a percent; a 5-hour one only holds until its reset. */
function storedLimitOf(kind: Kind, kept: StoredLimit | undefined, now: number): Limit | undefined {
  if (!kept) return undefined
  let reset = Date.parse(kept.resetsAt)
  if (reset > now) return { percentUsed: kept.percentUsed, resetsAt: kept.resetsAt, observedAt: kept.observedAt }
  if (kind !== 'seven_day') return undefined
  while (reset <= now) reset += 7 * DAY_MS
  return { resetsAt: new Date(reset).toISOString() }
}

/* The limit this session holds, received at liveAt, or the one stored by any session,
   whichever was received later. A live limit of unknown age loses to a stored one. */
function limitOf(kind: Kind, live: readonly SessionRateLimit[], liveAt: number | undefined, kept: StoredLimit | undefined, now: number) {
  const found = live.find(l => l.kind === kind && l.resetsAt)
  const stored = storedLimitOf(kind, kept, now)
  if (!found) return stored
  const mine: Limit = { percentUsed: found.percentUsed, resetsAt: found.resetsAt!, observedAt: liveAt }
  if (!stored) return mine
  if (liveAt === undefined) return stored
  return stored.observedAt !== undefined && stored.observedAt > liveAt ? stored : mine
}

const latestEntry = (plans: Ledger, subscription: string): PlanEntry | undefined => {
  const entries = plans[subscription] ?? []
  return entries[entries.length - 1]
}

/* Every stored instant the card may show, labeled by the helper under its epoch ms. */
function labelArgs(regimes: Regimes, plans: Ledger, subscription: string, now: number) {
  const instants = new Set<number>([now])
  for (const w of WINDOWS) {
    const r = currentRegime(regimes, subscription, w.kind)
    if (r && r.startedAt > 0) instants.add(r.startedAt)
  }
  const entry = latestEntry(plans, subscription)
  if (entry?.profileFetchedAt) instants.add(entry.profileFetchedAt)
  if (entry?.lastSeenAt) instants.add(entry.lastSeenAt)
  return [...instants].flatMap(ms => ['--label', `${ms},${new Date(ms).toISOString()}`])
}

async function queueNotices(host: Host, subscription: string, drafts: readonly NoticeDraft[], now: number) {
  if (drafts.length === 0) return
  const queue = ((await host.get(NOTICES_KEY)) ?? []) as Notice[]
  const ids = new Set(queue.map(n => n.id))
  const added = drafts
    .filter(d => !ids.has(d.id))
    .map(d => ({ ...d, org: subscription, at: now, isToasted: false, isSeen: false }) as Notice)
  if (added.length === 0) return
  const next = [...queue, ...added]
  await host.set(NOTICES_KEY, next.slice(Math.max(0, next.length - KEPT_NOTICES)))
}

function planChangedText(event: { from: PlanEntry; to: PlanEntry; between: [number, number] }, labels: Record<string, string>, profile: Profile) {
  const from = labels[String(event.between[0])] ?? 'the previous check'
  const to =
    (profile.fetchedAt && Date.parse(profile.fetchedAt) === event.between[1] ? profile.fetchedLabel : undefined) ??
    labels[String(event.between[1])] ??
    'now'
  return `Plan changed: ${event.from.label} → ${event.to.label} (between ${from} and ${to}). Estimates restarted.`
}

function planReport(
  event: ReturnType<typeof observePlan>['event'],
  profile: Profile | null | undefined,
  labels: Record<string, string>,
  now: number,
): PlanReport {
  if (event.kind === 'unknown') {
    const known = event.lastKnown
    const on = known ? labels[String(known.lastSeenAt)] : undefined
    return {
      isUnknown: true,
      isStale: false,
      unknownReason: event.reason,
      lastKnown: known ? `${known.label}${on ? ` on ${on}` : ''}` : undefined,
    }
  }
  const fetchedAt = profile?.fetchedAt ? Date.parse(profile.fetchedAt) : NaN
  const label = event.kind === 'changed' ? event.to.label : undefined
  return {
    isUnknown: false,
    label: label ?? (profile ? planLabel(profile) : undefined),
    asOfLabel: profile?.fetchedLabel ?? undefined,
    isStale: Number.isFinite(fetchedAt) && now - fetchedAt > STALE_PROFILE_MS,
  }
}

/* A closed window that contains a regime start of its own subscription mixes two sets of
   limits, so it cannot tell how the API rounds. */
function isStraddling(r: WindowReadings & { org: string }, regimes: Regimes) {
  const reset = Date.parse(r.resetsAt)
  const start = reset - (SPAN_MS[r.kind] ?? 0)
  return (regimes[r.org] ?? []).some(
    (g: Regime) => !g.isUndone && (!g.kinds || g.kinds.includes(r.kind as Kind)) && g.startedAt > start && g.startedAt <= reset,
  )
}

function basisOf(e: Estimate | undefined, isUnpriced: boolean, sinceResetLabel: string | undefined) {
  const reset = sinceResetLabel ? ` · since reset ${sinceResetLabel}` : ''
  if (isUnpriced) return `Unpriced models in use: no estimate${reset}.`
  if (!e) return `No estimate yet: the limit has not reported a usable reading for this window${reset}.`
  const readings = e.isPriorOnly
    ? 'From past windows only: no tick read in this window yet'
    : `${e.readings} percent level${e.readings === 1 ? '' : 's'} read`
  const within = `within-window spread ${e.isWithinSpreadAssumed ? 'assumed' : 'measured'}`
  const between = e.isSpreadAssumed
    ? 'between-window spread assumed'
    : `between-window spread from ${e.pastWindows} past window${e.pastWindows === 1 ? '' : 's'}`
  return `${readings} · ${within} · ${between} · history weight ${e.pastWeight}${reset}`
}

const isUnpricedTally = (t: WindowTally) => t.unpricedRequests > MAX_UNPRICED_SHARE * (t.requests + t.unpricedRequests)

/* The percents of the active window a measure may record: this session's, from `given`,
   and the stored one when a session with these hooks stored it and it is not the same
   percent. Whether the stored one has a reading already is decided against the readings
   read just before they are written. */
function candidatesOf(
  w: (typeof WINDOWS)[number],
  limit: Limit,
  subscription: string,
  given: readonly SessionRateLimit[] | undefined,
  readAt: number,
  sessionId: string,
  kept: StoredLimit | undefined,
): Candidate[] {
  const key = windowKey(subscription, w.kind, limit.resetsAt)
  const candidates: Candidate[] = []
  const fresh = given?.find(l => l.kind === w.kind && l.resetsAt)
  if (fresh && windowKey(subscription, w.kind, fresh.resetsAt!) === key)
    candidates.push({ source: 'mine', tally: `${w.name}${AT_READ}`, percent: fresh.percentUsed, at: readAt, sessionId })
  const isMine = candidates.some(c => c.at === kept?.observedAt && c.sessionId === kept?.sessionId)
  if (
    kept?.sessionId &&
    kept.percentUsed !== undefined &&
    (kept.stamp ?? 0) === HOOKS_STAMP &&
    windowKey(subscription, w.kind, kept.resetsAt) === key &&
    !isMine
  )
    candidates.push({ source: 'stored', tally: `${w.name}${AT_STORED}`, percent: kept.percentUsed, at: kept.observedAt, sessionId: kept.sessionId })
  return candidates
}

/* Whether a level's bucket holds the reading at `at`, or a later one at that level that
   took its side. */
function isHeld(r: WindowReadings | undefined, percent: number, at: number) {
  const b = r?.byPct[String(percent)]
  return b !== undefined && (b.minAt === at || b.maxAt >= at)
}

const hasReadingAt = (r: WindowReadings | undefined, at: number) =>
  r !== undefined && Object.values(r.byPct).some(b => b.minAt === at || b.maxAt === at)

/* isFresh: `given` holds percents this session received at receivedAt, so they and the
   dollars counted up to then describe the same moment. Only such a measure records its
   own percents or shares its limits; every measure records a stored percent that has no
   reading yet. */
async function measure(
  host: Host,
  given: readonly SessionRateLimit[] | undefined,
  isFresh: boolean,
  receivedAt: number | undefined,
): Promise<Summary | undefined> {
  const now = await host.now()
  if (firstMeasureAt === undefined) firstMeasureAt = now
  const readAt = isFresh && receivedAt !== undefined ? receivedAt : now
  const live = given ?? (await host.rateLimits())
  if (isFresh) lastFreshAt = readAt
  const sessionId = await host.sessionId()
  let subscription = await resolveSubscription(host)

  let active: { w: (typeof WINDOWS)[number]; limit: Limit; candidates: Candidate[] }[] = []
  let storedLimits: StoredLimits = {}
  let out: WindowsOutput | undefined
  for (let attempt = 0; attempt < 2; attempt++) {
    storedLimits = ((await host.get(LIMITS_KEY)) ?? {}) as StoredLimits
    active = []
    for (const w of WINDOWS) {
      const kept = storedLimits[subscription]?.[w.kind]
      const limit = limitOf(w.kind, live, lastFreshAt, kept, now)
      if (limit) active.push({ w, limit, candidates: candidatesOf(w, limit, subscription, isFresh ? given : undefined, readAt, sessionId, kept) })
    }
    if (active.length === 0) {
      host.status('waiting for the first reply')
      return undefined
    }

    const regimes = ((await host.get(REGIMES_KEY)) ?? {}) as Regimes
    const plans = ((await host.get(PLANS_KEY)) ?? {}) as Ledger
    const extra: string[] = []
    for (const { w, limit, candidates } of active) {
      const since = new Date(Date.parse(limit.resetsAt) - w.spanMs).toISOString()
      extra.push('--window', `${w.name},${since},${limit.resetsAt}`)
      for (const c of candidates)
        extra.push('--window', `${c.tally},${since},${limit.resetsAt},${new Date(c.at).toISOString()},${c.sessionId}`)
    }
    extra.push('--window', `last24h,${new Date(now - DAY_MS).toISOString()},${new Date(now).toISOString()}`)
    extra.push('--window', `last7d,${new Date(now - 7 * DAY_MS).toISOString()},${new Date(now).toISOString()}`)
    extra.push(...labelArgs(regimes, plans, subscription, now))
    const result = await runHelper<WindowsOutput>(host, extra, 120_000)
    if (!result.out?.windows) {
      host.status('unavailable')
      host.log(`usage-dollars: ${result.error ?? 'no windows in the helper output'}`)
      return undefined
    }
    out = result.out
    if (out.orgSource === 'session' && out.org) sessionOrg = out.org
    const reported = subscriptionOf(out.org)
    if (reported === subscription) break
    subscription = reported
    if (attempt === 1) break
  }
  if (!out?.windows) return undefined
  lastSubscription = subscription
  const labels = out.labels ?? {}
  const profile = out.profile ?? null

  /* A stored limit gives way to one received later, or to the next window's. */
  const liveLimits = isFresh ? live.filter(l => l.resetsAt && WINDOWS.some(w => w.kind === l.kind)) : []
  if (liveLimits.length > 0) {
    const stored = ((await host.get(LIMITS_KEY)) ?? {}) as StoredLimits
    const mine = { ...stored[subscription] }
    let isChanged = false
    for (const l of liveLimits) {
      const was = mine[l.kind] as StoredLimit | undefined
      if (was && Date.parse(was.resetsAt) >= Date.parse(l.resetsAt!) && was.observedAt >= readAt) continue
      mine[l.kind] = { percentUsed: l.percentUsed, resetsAt: l.resetsAt!, observedAt: readAt, sessionId, stamp: HOOKS_STAMP }
      isChanged = true
    }
    if (isChanged) await host.set(LIMITS_KEY, { ...stored, [subscription]: mine })
  }

  /* Hooks of another stamp that stored a percent since this module first measured. */
  for (const l of Object.values(storedLimits[subscription] ?? {})) {
    const stamp = l.stamp ?? 0
    if (stamp !== HOOKS_STAMP && l.observedAt > (firstMeasureAt ?? now)) diagnostics.otherHooks = stamp < HOOKS_STAMP ? 'older' : 'newer'
  }

  /* A guessed subscription must not write readings; with none at all every request is
     counted, as on a machine without bridge-session records. A reading takes its percent
     from a candidate, and only for the window the dollars were scanned for; its dollars
     and their features end where the percent was received. Readings priced with another
     table are dropped. */
  const mayRecord = out.org === null || out.org === undefined || out.orgSource === 'session' || out.orgSource === 'profile'
  const pricesId = out.pricesId
  const tallies = out.windows
  const { kept, attempts } = await exclusively(async () => {
    const storedReadings = ((await host.get(READINGS_KEY)) ?? {}) as StoredReadings
    const readings = Object.fromEntries(Object.entries(storedReadings).filter(([, r]) => r.pricesId === pricesId)) as StoredReadings
    diagnostics.droppedForPrices += Object.keys(storedReadings).length - Object.keys(readings).length
    const attempts: Attempt[] = []
    for (const { w, limit, candidates } of active) {
      const key = windowKey(subscription, w.kind, limit.resetsAt)
      for (const c of candidates) {
        if (c.source === 'stored' && hasReadingAt(readings[key], c.at)) continue
        const tally = tallies[c.tally]
        const attempt: Attempt = { title: w.title, key, c }
        attempts.push(attempt)
        if (!mayRecord) attempt.outcome = 'unattributed'
        else if (tally && isUnpricedTally(tally)) attempt.outcome = 'unpriced'
        else if (tally) {
          const was = readings[key] ?? { kind: w.kind, resetsAt: limit.resetsAt, byPct: {}, org: subscription, pricesId }
          readings[key] = { ...record(was, c.percent, tally.usd, c.at, tally.slackUsd ?? 0, tally.byFeature), org: subscription, pricesId }
        }
      }
    }
    const kept = withinSize(
      Object.fromEntries(Object.entries(readings).filter(([, r]) => Date.parse(r.resetsAt) > now - READINGS_KEPT_MS)) as StoredReadings,
      now,
    )
    await host.set(READINGS_KEY, kept)
    return { kept, attempts }
  })
  const outcomes: Diagnostics['outcomes'] = {}
  for (const a of attempts) {
    const outcome = a.outcome ?? (isHeld(kept[a.key], a.c.percent, a.c.at) ? 'recorded' : 'missing')
    outcomes[a.title] = [...(outcomes[a.title] ?? []), { source: a.c.source, outcome }]
  }
  for (const [title, list] of Object.entries(outcomes)) diagnostics.outcomes[title] = list

  const plans = ((await host.get(PLANS_KEY)) ?? {}) as Ledger
  const observedPlan = observePlan(plans, profile, subscription, now)
  if (!isSame(observedPlan.ledger, plans)) await host.set(PLANS_KEY, observedPlan.ledger)

  const promotions = ((await host.get(PROMOTIONS_KEY)) ?? {}) as Promotions
  const observedPromos = observePromotions(promotions, profile, subscription, now)
  if (!isSame(observedPromos.stored, promotions)) await host.set(PROMOTIONS_KEY, observedPromos.stored)

  const added = [...(observedPlan.regime ? [observedPlan.regime] : []), ...observedPromos.regimes]
  let regimes = ((await host.get(REGIMES_KEY)) ?? {}) as Regimes
  if (added.length > 0) {
    regimes = addRegimes(regimes, subscription, added)
    await host.set(REGIMES_KEY, regimes)
  }

  const drafts: NoticeDraft[] = [...observedPromos.notices]
  const event = observedPlan.event
  if (event.kind === 'changed' && profile)
    drafts.push({ id: `plan:${subscription}:${event.to.fingerprint}`, kind: 'plan-changed', text: planChangedText(event, labels, profile) })

  const all = Object.values(kept)
  const resolution = resolutionOf(all)
  const roundingSeen = roundingEvidence(
    all.filter(r => Date.parse(r.resetsAt) <= now && !isStraddling(r, regimes)),
    resolution,
  )
  const rounding = roundingSeen.rule
  const history = ((await host.get(HISTORY_KEY)) ?? {}) as History
  const observations = history[subscription]?.observations ?? []

  const windows: WindowState[] = []
  for (const { w, limit } of active) {
    const tally = out.windows[w.name]
    if (!tally) continue
    const startedAt = regimeStart(regimes, subscription, w.kind)
    const regime = currentRegime(regimes, subscription, w.kind)
    /* Closed windows of this subscription and regime: one past point each, and the
       crossings that measure the within-window spread. */
    const closed = all
      .filter(r => r.org === subscription && r.kind === w.kind && Date.parse(r.resetsAt) <= now && Date.parse(r.resetsAt) >= startedAt)
      .map(r => regimeView(r, startedAt))
    const rejections = observations.filter(o => Date.parse(o.resetsAt) > now - HISTORY_DAYS * DAY_MS)
    const spread = calibrateOmega(closed, w.kind, now, resolution, rounding)
    const past = pastPoints(closed, rejections, w.kind, resolution, rounding, spread.omega).filter(p => p.at >= startedAt)
    const key = windowKey(subscription, w.kind, limit.resetsAt)
    const stored = kept[key]
    const current = stored ? regimeView(stored, startedAt) : undefined
    const isUnpriced = isUnpricedTally(tally)
    const e =
      current && !isUnpriced
        ? estimate(current, tally.usd, {
            resolution,
            rounding,
            past,
            kind: w.kind,
            now,
            livePercent: limit.observedAt !== undefined && now - limit.observedAt <= FRESH_MS ? limit.percentUsed : undefined,
            spread,
          })
        : undefined
    if (e?.isPriorContradicted) drafts.push({ id: `inferred:${key}`, kind: 'inferred', text: INFERRED_TEXT })
    windows.push({
      title: w.title,
      short: w.short,
      resetsAt: limit.resetsAt,
      tally,
      estimate: e,
      isUnpriced,
      sinceResetLabel: regime?.reason === 'manual' ? labels[String(regime.startedAt)] : undefined,
      percent: limit.percentUsed,
      percentAt: limit.percentUsed !== undefined ? limit.observedAt : undefined,
      calibration: {
        ...calibrationOf({ current, resolution, spread, prior: prior(past, w.kind, now), rounding: roundingSeen }),
        closedWindows: closed.filter(r => Object.keys(r.byPct).length > 0).length,
        rounding,
        halfWidth: e ? Math.sqrt(e.allowance.high / e.allowance.low) - 1 : undefined,
      },
    })
  }
  await queueNotices(host, subscription, drafts, now)

  const queue = ((await host.get(NOTICES_KEY)) ?? []) as Notice[]
  const mine = queue.filter(n => n.org === subscription)
  const isPlanUnseen = mine.some(n => n.kind === 'plan-changed' && !n.isSeen)
  host.status(statusOf({ windows }, isPlanUnseen))

  const isShared = Object.keys(observedPlan.ledger).length > 1
  const notices = [
    ...mine
      .filter(n => n.kind === 'plan-changed' && n.at > now - NOTICE_SHOWN_MS)
      .map(n => n.text),
    ...activePromotions(observedPromos.stored, subscription).map(t => (isShared ? `${t} Not attributable to one subscription.` : t)),
    ...mine
      .filter(n => n.kind === 'promotion' && /^promo-(end|gone):/.test(n.id) && n.at > now - NOTICE_SHOWN_MS)
      .map(n => n.text),
    ...(windows.some(s => s.estimate?.isPriorContradicted) ? [INFERRED_TEXT] : []),
  ]

  const summary: Summary = {
    subscription,
    orgSource: out.orgSource,
    windows,
    plan: planReport(event, profile, labels, now),
    notices,
    last24hUsd: out.windows.last24h?.usd,
    last7dX: out.windows.last7d?.byFeature,
    sinceResetLabel: windows.find(s => s.sinceResetLabel)?.sinceResetLabel,
    files: out.files,
    ms: out.ms,
  }
  if (mayRecord) {
    meterContext = { subscription, pricesId }
    follow(host, meterContext)
  }
  return summary
}

/* The backfill and the model fit after a measure, one run at a time; a measure that ends
   while one runs queues the next. Neither delays nor fails the measure. */
function follow(host: Host, context: MeterContext) {
  queuedFollowUp = { host, context }
  if (followUp) return
  const takeQueued = () => {
    const next = queuedFollowUp
    queuedFollowUp = undefined
    return next
  }
  followUp = (async () => {
    try {
      for (let next = takeQueued(); next; next = takeQueued()) {
        const { host: h, context: c } = next
        await backfillOnce(h, c).catch(error => h.log(`usage-dollars: backfill: ${String(error)}`))
        await refreshMeter(h, c).catch(error => h.log(`usage-dollars: model fit: ${String(error)}`))
      }
    } finally {
      followUp = undefined
    }
  })().catch(() => undefined)
}

/** The backfill and model fit that measures started, settled once none is left. */
export function backfillSettled(): Promise<void> {
  return followUp ?? Promise.resolve()
}

const toleranceOf = (usd: number) => Math.max(FEATURE_TOLERANCE_RELATIVE * Math.abs(usd), FEATURE_TOLERANCE_ABSOLUTE)

/* One bucket side without per-feature dollars, and the --window name its dollars come
   back under. */
type BackfillSide = { key: string; pct: string; isMin: boolean; at: number; usd: number; name: string }

/* Up to BACKFILL_MAX_SPECS window specs for the sides that lack features, newest windows
   first, open ones included; sides read at the same moment share a spec. Windows the
   backfill could not rebuild are left out. */
function backfillPlanOf(readings: StoredReadings, context: MeterContext) {
  const sides: BackfillSide[] = []
  const names = new Map<string, string>()
  const newestFirst = Object.entries(readings)
    .filter(([, r]) => r.org === context.subscription && r.pricesId === context.pricesId && !r.featuresUnverified && SPAN_MS[r.kind])
    .sort(([, a], [, b]) => Date.parse(b.resetsAt) - Date.parse(a.resetsAt))
  for (const [key, r] of newestFirst) {
    const since = new Date(Date.parse(r.resetsAt) - (SPAN_MS[r.kind] ?? 0)).toISOString()
    for (const [pct, b] of Object.entries(r.byPct))
      for (const isMin of [true, false]) {
        if ((isMin ? b.minX : b.maxX) !== undefined) continue
        const at = isMin ? b.minAt : b.maxAt
        const spec = `${since},${r.resetsAt},${new Date(at).toISOString()}`
        let name = names.get(spec)
        if (name === undefined) {
          if (names.size >= BACKFILL_MAX_SPECS) return { sides, names }
          name = `bf${names.size}`
          names.set(spec, name)
        }
        sides.push({ key, pct, isMin, at, usd: isMin ? b.minUsd : b.maxUsd, name })
      }
  }
  return { sides, names }
}

/* The window with one side's per-feature dollars as record() stores them: new keys
   appended in sorted order, values in units of 1e-6. */
function withSideFeatures(r: StoredReading, pct: string, isMin: boolean, x: Record<string, number>): StoredReading {
  const b = r.byPct[pct]
  if (!b) return r
  const known = r.features ?? []
  const features = [
    ...known,
    ...Object.keys(x)
      .filter(f => !known.includes(f))
      .sort(),
  ]
  const values = features.map(f => Math.round((x[f] ?? 0) * X_UNIT) / X_UNIT)
  return { ...r, features, byPct: { ...r.byPct, [pct]: isMin ? { ...b, minX: values } : { ...b, maxX: values } } }
}

/* One helper call that rescans the dollars of sides stored without features. A side is
   filled when its rescanned dollars match the stored ones; otherwise its window is marked
   and not tried again. A failed call changes nothing; the next measure tries again. */
async function backfillOnce(host: Host, context: MeterContext) {
  const plan = backfillPlanOf(((await host.get(READINGS_KEY)) ?? {}) as StoredReadings, context)
  if (plan.sides.length === 0) return
  const extra = [...plan.names].flatMap(([spec, name]) => ['--window', `${name},${spec}`])
  const result = await runHelper<WindowsOutput>(host, extra, BACKFILL_TIMEOUT_MS)
  const out = result.out
  if (!out?.windows) {
    host.log(`usage-dollars: backfill: ${result.error ?? 'no windows in the helper output'}`)
    return
  }
  if (subscriptionOf(out.org) !== context.subscription || out.pricesId !== context.pricesId) {
    host.log('usage-dollars: backfill: the helper scanned another subscription or price table')
    return
  }
  const tallies = out.windows
  const now = await host.now()
  await exclusively(async () => {
    const readings = ((await host.get(READINGS_KEY)) ?? {}) as StoredReadings
    const next = { ...readings }
    let isChanged = false
    for (const s of plan.sides) {
      const r = next[s.key]
      const b = r?.byPct[s.pct]
      const x = tallies[s.name]
      if (!r || !b || r.featuresUnverified || !x?.byFeature) continue
      const isUnchanged = (s.isMin ? b.minAt : b.maxAt) === s.at && (s.isMin ? b.minUsd : b.maxUsd) === s.usd
      if (!isUnchanged || (s.isMin ? b.minX : b.maxX) !== undefined) continue
      next[s.key] =
        Math.abs(x.usd - s.usd) <= toleranceOf(s.usd) ? withSideFeatures(r, s.pct, s.isMin, x.byFeature) : { ...r, featuresUnverified: true }
      isChanged = true
    }
    if (isChanged) await host.set(READINGS_KEY, withinSize(next, now))
  })
}

/* Closed windows of one kind in the subscription's current regime, as seen from it, that
   hold readings, with their store keys. */
function regimeWindowsOf(readings: StoredReadings, context: MeterContext, kind: Kind, startedAt: number, now: number) {
  return Object.entries(readings)
    .filter(
      ([, r]) =>
        r.org === context.subscription &&
        r.pricesId === context.pricesId &&
        r.kind === kind &&
        Date.parse(r.resetsAt) <= now &&
        Date.parse(r.resetsAt) >= startedAt,
    )
    .map(([key, r]) => ({ key, w: regimeView(r, startedAt) as StoredReading }))
    .filter(({ w }) => Object.keys(w.byPct).length > 0)
}

/* What the model fit rests on, read from the store. */
async function meterInputOf(host: Host, context: MeterContext) {
  const now = await host.now()
  const readings = ((await host.get(READINGS_KEY)) ?? {}) as StoredReadings
  const regimes = ((await host.get(REGIMES_KEY)) ?? {}) as Regimes
  const all = Object.values(readings).filter(r => r.pricesId === context.pricesId)
  const resolution = resolutionOf(all)
  const regimeStarts: Record<string, number> = {}
  const closed: Record<string, { key: string; w: StoredReading }[]> = {}
  for (const kind of KINDS) {
    regimeStarts[kind] = regimeStart(regimes, context.subscription, kind)
    closed[kind] = regimeWindowsOf(readings, context, kind, regimeStarts[kind] ?? 0, now)
  }
  const qualifying = (kind: Kind) => (closed[kind] ?? []).filter(({ w }) => isFeatureComplete(w))
  return {
    now,
    resolution,
    regimeStarts,
    closed,
    fiveHour: qualifying('five_hour'),
    weekly: qualifying('seven_day'),
    /* Closed windows of every subscription that may show the rounding rule, as the measure
       takes them. */
    forRounding: all.filter(r => Date.parse(r.resetsAt) <= now && !isStraddling(r, regimes)),
  }
}

/* Scores the windows that qualify since the stored fit, under its weights for their kind
   and under M0, before the refit; a kind's records are cleared when its regime or the
   price table changed. */
function prospectiveOf(was: MeterEntry | undefined, input: Awaited<ReturnType<typeof meterInputOf>>, pricesId: string | undefined) {
  let records = [...(was?.prospective ?? [])]
  if (!was) return records
  for (const kind of KINDS) {
    if (was.regimeStarts[kind] !== input.regimeStarts[kind] || was.pricesId !== pricesId) {
      records = records.filter(p => p.kind !== kind)
      continue
    }
    const fit = was.fits?.[kind]
    if (!fit) continue
    const seen = new Set(was.included?.[kind] ?? [])
    const fresh = (kind === 'five_hour' ? input.fiveHour : input.weekly).filter(({ key }) => !seen.has(key)).map(({ w }) => w)
    records.push(...prospectiveScore(fit, fresh, { resolution: input.resolution, rounding: was.rounding }))
  }
  return records.slice(-PROSPECTIVE_KEPT)
}

/* The stored model fit of the subscription, refitted when its fingerprint changed: model
   selection on the 5-hour windows under the union, the rounding rule from the weighted
   views it gives, selection again under that rule, then the transfer to the weeks. The
   estimates do not use it. */
async function refreshMeter(host: Host, context: MeterContext): Promise<MeterEntry | undefined> {
  const input = await meterInputOf(host, context)
  const fingerprint = fingerprintOf({
    fiveHour: input.fiveHour,
    weekly: input.weekly,
    regimeStarts: input.regimeStarts,
    pricesId: context.pricesId,
    schema: SCHEMA,
    stamp: HOOKS_STAMP,
  })
  const stored = ((await host.get(METER_KEY)) ?? {}) as StoredMeter
  const was = stored[context.subscription]
  if (was?.fingerprint === fingerprint) return was
  const prospective = prospectiveOf(was, input, context.pricesId)
  const { resolution } = input
  const fiveHour = input.fiveHour.map(({ w }) => w)
  const first = selectModel(fiveHour, { resolution, rounding: 'union' })
  const views = input.forRounding.flatMap(r => weightedView(r, first.weights) ?? [])
  const rounding = roundingEvidence(views, resolution).rule
  const selection = rounding === 'union' ? first : selectModel(fiveHour, { resolution, rounding })
  const transfer = transferCheck(input.weekly.map(({ w }) => w), selection.weights, { resolution, rounding })
  const entry: MeterEntry = {
    fingerprint,
    included: { five_hour: input.fiveHour.map(({ key }) => key), seven_day: input.weekly.map(({ key }) => key) },
    regimeStarts: input.regimeStarts,
    ...(context.pricesId !== undefined ? { pricesId: context.pricesId } : {}),
    rounding,
    selection,
    transfer,
    fits: {
      five_hour: {
        weights: selection.weights,
        omega: selection.fits[selection.selected]?.omega ?? UNFITTED_OMEGA,
        omegaM0: selection.fits.M0?.omega ?? UNFITTED_OMEGA,
      },
      seven_day: transfer.isRejected
        ? { weights: UNIT_WEIGHTS, omega: transfer.omega.M0, omegaM0: transfer.omega.M0 }
        : { weights: selection.weights, omega: transfer.omega.selected, omegaM0: transfer.omega.M0 },
    },
    prospective,
  }
  if (!isSame(entry, was)) await host.set(METER_KEY, { ...stored, [context.subscription]: entry })
  return entry
}

/** The status line: what is left of each window's allowance. */
export function statusOf(summary: Pick<Summary, 'windows'>, isPlanUnseen: boolean) {
  return statusLine(
    summary.windows.map(s => ({ short: s.short, usedUsd: s.tally.usd, allowance: s.estimate?.allowance, left: s.estimate?.left })),
    isPlanUnseen,
  )
}

/* One scan at a time, at most once a minute unless forced or fresh. A fresh call that
   meets a running scan is queued and runs, forced, once that scan settles. */
export function refresh(host: Host, limits?: readonly SessionRateLimit[], isForced = false, isFresh = false, receivedAt?: number) {
  if (running) {
    if (isFresh) pendingFresh = { host, limits, receivedAt }
    return running
  }
  if (!isForced && !isFresh && Date.now() - lastRunAt < MIN_GAP_MS) return Promise.resolve(last)
  lastRunAt = Date.now()
  running = measure(host, limits, isFresh, receivedAt)
    .then(summary => (last = summary ?? last))
    .catch(error => {
      host.log(`usage-dollars: ${String(error)}`)
      return last
    })
    .finally(() => {
      running = undefined
      const queued = pendingFresh
      pendingFresh = undefined
      if (queued) void refresh(queued.host, queued.limits, true, true, queued.receivedAt)
    })
  return running
}

/** A forced measure that starts after any measure already running. */
export async function remeasure(host: Host) {
  if (running) await running
  return refresh(host, undefined, true)
}

/* Past rate-limit rejections, each a window seen exactly full; rescanned every six hours. */
export async function refreshHistory(host: Host) {
  const subscription = await resolveSubscription(host)
  const now = await host.now()
  const kept = ((await host.get(HISTORY_KEY)) ?? {}) as History
  if (kept[subscription] && now - kept[subscription].scannedAt < HISTORY_REFRESH_MS) return
  const { out, error } = await runHelper<HelperBase & { observations?: Observation[] }>(
    host,
    ['--history', String(HISTORY_DAYS)],
    180_000,
  )
  if (!out?.observations) {
    host.log(`usage-dollars: history: ${error ?? 'no observations'}`)
    return
  }
  const stored = ((await host.get(HISTORY_KEY)) ?? {}) as History
  await host.set(HISTORY_KEY, { ...stored, [subscriptionOf(out.org)]: { scannedAt: now, observations: out.observations } })
  void refresh(host, undefined, true)
}

/** Restarts the estimates of the session's subscription from now. */
export async function resetEstimates(host: Host) {
  const subscription = await resolveSubscription(host)
  const now = await host.now()
  const regimes = ((await host.get(REGIMES_KEY)) ?? {}) as Regimes
  await host.set(REGIMES_KEY, startOver(regimes, subscription, now))
  await remeasure(host)
}

/** Undoes the latest reset when nothing observed has followed it. */
export async function undoReset(host: Host) {
  const subscription = await resolveSubscription(host)
  const regimes = ((await host.get(REGIMES_KEY)) ?? {}) as Regimes
  const result = undoStartOver(regimes, subscription)
  if (result.isUndone) await host.set(REGIMES_KEY, result.regimes)
  await remeasure(host)
  return result.isUndone
}

/** Marks every queued notice seen: the card has been shown. */
export async function markNoticesSeen(host: Host) {
  const queue = ((await host.get(NOTICES_KEY)) ?? []) as Notice[]
  if (queue.every(n => n.isSeen)) return
  await host.set(NOTICES_KEY, queue.map(n => ({ ...n, isSeen: true })))
}

/** The texts of this subscription's notices not toasted yet, marked toasted. */
export async function takeToasts(host: Host) {
  if (!lastSubscription) return []
  const queue = ((await host.get(NOTICES_KEY)) ?? []) as Notice[]
  const due = queue.filter(n => n.org === lastSubscription && !n.isToasted)
  if (due.length === 0) return []
  const ids = new Set(due.map(n => n.id))
  await host.set(NOTICES_KEY, queue.map(n => (ids.has(n.id) ? { ...n, isToasted: true } : n)))
  return due.map(n => n.text)
}

export function toReport(summary: Summary, now: number): UsageReport {
  const windows: WindowReport[] = summary.windows.map(s => ({
    title: s.title,
    short: s.short,
    usedUsd: s.tally.usd,
    requests: s.tally.requests,
    resetLong: s.tally.resetLong ?? s.resetsAt,
    resetIn: s.tally.resetIn ?? '',
    left: s.estimate
      ? { value: Math.max(0, s.estimate.left.value), low: Math.max(0, s.estimate.left.low), high: Math.max(0, s.estimate.left.high) }
      : undefined,
    allowance: s.estimate?.allowance,
    confidence: s.estimate?.confidence,
    nextTick: s.estimate?.nextTick,
    pastWeight: s.estimate?.pastWeight,
    isPriorContradicted: s.estimate?.isPriorContradicted,
    isSpreadAssumed: s.estimate?.isSpreadAssumed,
    percent: s.percent,
    percentAgeMinutes: s.percentAt !== undefined ? Math.max(0, Math.round((now - s.percentAt) / MINUTE_MS)) : undefined,
    basis: basisOf(s.estimate, s.isUnpriced, s.sinceResetLabel),
    isCalibrated: s.calibration.isCalibrated,
  }))
  const widest = summary.windows[summary.windows.length - 1]
  const byModel: ModelSpend[] = Object.entries(widest?.tally.byModel ?? {})
    .map(([model, spend]) => ({ model, ...spend }))
    .sort((a, b) => b.usd - a.usd)
  return {
    type: 'windows',
    plan: summary.plan,
    notices: summary.notices,
    last24hUsd: summary.last24hUsd,
    sinceResetLabel: summary.sinceResetLabel,
    windows,
    byModel,
    byModelTitle: `By model · ${(widest?.title ?? '').toLowerCase()}`,
    notes: notesOf(widest?.tally),
    files: summary.files,
    ms: summary.ms,
  }
}

function notesOf(t: Omit<WindowTally, 'byModel' | 'usd' | 'requests'> | undefined) {
  const notes: string[] = []
  if (t && t.otherSubscriptionsUsd > 0)
    notes.push(`Other subscriptions spent ${money(t.otherSubscriptionsUsd)} in this period; not counted here.`)
  if (t && t.unattributedUsd > 0)
    notes.push(`${money(t.unattributedUsd)} came from sessions with no subscription record; not counted here.`)
  if (t && t.unpricedRequests > 0)
    notes.push(`${t.unpricedRequests} requests to unpriced models (${t.unpricedModels.join(', ')}); not counted here.`)
  return notes
}

/** Spending in a range: `range` is the helper's `--report` or `--report-local` argument pair. */
export async function spendReport(host: Host, range: readonly string[]): Promise<SpendReport | { error: string }> {
  const { out, error } = await runHelper<ReportOutput>(host, range, 180_000)
  if (!out) return { error: error ?? 'no report' }
  const notes = notesOf(out)
  if (out.transcriptsBeginLabel)
    notes.push(`Transcripts on this machine begin ${out.transcriptsBeginLabel}; earlier spending is not included.`)
  return {
    type: 'report',
    fromLabel: out.fromLabel,
    toLabel: out.toLabel,
    usedUsd: out.usd,
    requests: out.requests,
    byDay: out.byDay,
    byModel: Object.entries(out.byModel)
      .map(([model, spend]) => ({ model, ...spend }))
      .sort((a, b) => b.usd - a.usd),
    notes,
  }
}

/** What this session has seen of other sessions and of its own readings. */
export const diagnosticsOf = (): Readonly<Diagnostics> => diagnostics

type CheckSummary = { sessions: number; medianRatio: number | null; lowRatio: number | null; highRatio: number | null; error?: string }

const NOT_RECORDED: Record<'unpriced' | 'unattributed', string> = {
  unpriced: 'too many of its requests go to unpriced models (see Prices)',
  unattributed: 'the subscription is a guess (see Subscription)',
}

const titles = (list: readonly string[]) => list.join(' and ')

function subscriptionItem(orgSource: OrgSource | null | undefined, hasOrg: boolean): CheckItem {
  const label = 'Subscription'
  if (orgSource === 'most recent')
    return {
      label,
      state: 'fail',
      text: 'Only guessed, from the most recently used one, so no readings are recorded. Sign in to Claude Code (/login).',
    }
  if (!hasOrg) return { label, state: 'info', text: 'None (an API key): there are no limits to read and no estimates.' }
  return {
    label,
    state: 'ok',
    text: orgSource === 'session' ? "Named by this session's own record." : 'Named by the signed-in profile.',
  }
}

function readingsItem(outcomes: Diagnostics['outcomes']): CheckItem {
  const label = 'Readings'
  const entries = Object.entries(outcomes)
  const missing = entries.filter(([, list]) => list.some(o => o.outcome === 'missing')).map(([title]) => title)
  if (missing.length > 0)
    return {
      label,
      state: 'fail',
      text: `A percent of the ${titles(missing)} was not recorded and nothing explains it. Please report it, with the debug log.`,
    }
  const reasons = entries.flatMap(([title, list]) =>
    list
      .map(o => o.outcome)
      .filter((o): o is 'unpriced' | 'unattributed' => o === 'unpriced' || o === 'unattributed')
      .map(o => `${title}: not recorded, ${NOT_RECORDED[o]}`),
  )
  if (reasons.length > 0) return { label, state: 'info', text: `${[...new Set(reasons)].join('; ')}.` }
  if (entries.length > 0) return { label, state: 'ok', text: `Recorded for the ${titles(entries.map(([title]) => title))}.` }
  return { label, state: 'info', text: 'None received in this session yet: a reading is taken after every reply.' }
}

/* The subscription's stored windows by the state of their per-feature dollars: complete;
   marked by the backfill; waiting for it; or carrying features that do not add up. */
function breakdownOf(readings: StoredReadings, subscription: string) {
  const counts = { total: 0, complete: 0, unverified: 0, waiting: 0, inconsistent: 0 }
  for (const r of Object.values(readings)) {
    if (r.org !== subscription || Object.keys(r.byPct).length === 0) continue
    counts.total++
    if (isFeatureComplete(r)) counts.complete++
    else if (r.featuresUnverified) counts.unverified++
    else if (Object.values(r.byPct).some(b => !b.minX || !b.maxX)) counts.waiting++
    else counts.inconsistent++
  }
  return counts
}

function breakdownItem(readings: StoredReadings, subscription: string): CheckItem {
  const label = 'Model breakdown'
  const { total, complete, unverified, waiting, inconsistent } = breakdownOf(readings, subscription)
  if (total === 0) return { label, state: 'info', text: 'No stored windows yet.' }
  const carry = `${complete} of ${total} stored window${total === 1 ? ' carries' : 's carry'} dollars per model and token class`
  const wait = waiting > 0 ? ` ${waiting} wait for the backfill, which runs after each measure.` : ''
  const failures: string[] = []
  if (unverified > 0)
    failures.push(
      `${unverified} could not be rebuilt: the transcripts no longer give their stored dollars, so the model fit leaves them out.`,
    )
  if (inconsistent > 0)
    failures.push(`${inconsistent} carry dollars per model that do not add up to their dollars. Please report it, with the debug log.`)
  if (failures.length > 0) return { label, state: 'fail', text: `${carry}; ${failures.join(' ')}${wait}` }
  return { label, state: 'info', text: `${carry}.${wait}` }
}

function pricesItem(check: CheckSummary, unpriced: readonly string[]): CheckItem {
  const label = 'Prices'
  const update = 'Update PRICES in scripts/usage-cost.mjs; doing so drops the stored readings and calibration starts again.'
  const failures: string[] = []
  if (unpriced.length > 0) failures.push(`More than 2% of the ${titles(unpriced)}'s requests go to unpriced models.`)
  const { medianRatio: median, lowRatio: low, highRatio: high, sessions } = check
  const over = `over ${sessions} session${sessions === 1 ? '' : 's'}`
  if (median !== null && (median < MIN_PRICE_RATIO || median > MAX_PRICE_RATIO))
    failures.push(`These dollars are ${median} times Claude Code's own costs (median ${over}).`)
  if (failures.length > 0) return { label, state: 'fail', text: `${failures.join(' ')} ${update}` }
  if (check.error) return { label, state: 'info', text: `Not compared with Claude Code's own costs: ${check.error}` }
  if (median === null) return { label, state: 'info', text: "No session of at least $0.50 to compare with Claude Code's own costs." }
  return {
    label,
    state: 'ok',
    text: `These dollars are ${median} times Claude Code's own costs (median ${over}; 5th to 95th percentile ${low} to ${high}).`,
  }
}

/** The setup check: a forced measure, then the helper, the subscription, other sessions'
    hooks and price table, this session's readings, and the prices. */
export async function checkReport(host: Host): Promise<CheckReport> {
  const summary = await remeasure(host)
  const who = await runHelper<HelperBase>(host, ['--whoami'], 30_000).catch(error => ({ out: undefined, error: String(error) }))
  if (!who.out)
    return {
      type: 'check',
      items: [
        {
          label: 'Helper',
          state: 'fail',
          text: `The transcript scan does not run (${who.error ?? 'no output'}). Install Node.js 18 or later on PATH, then restart Claude Code.`,
        },
      ],
    }
  const items: CheckItem[] = [{ label: 'Helper', state: 'ok', text: 'Node.js runs the transcript scan.' }]
  items.push(subscriptionItem(summary ? summary.orgSource : who.out.orgSource, summary ? summary.subscription !== NONE : Boolean(who.out.org)))

  const { otherHooks, droppedForPrices, outcomes } = diagnostics
  items.push(
    otherHooks === 'older'
      ? {
          label: 'Other hooks',
          state: 'fail',
          text: 'A session running older hooks stored a percent since this one started. Restart the other sessions, and load only one copy of the plugin.',
        }
      : otherHooks === 'newer'
        ? {
            label: 'Other hooks',
            state: 'fail',
            text: 'A session running newer hooks stored a percent since this one started. Restart this session, and load only one copy of the plugin.',
          }
        : { label: 'Other hooks', state: 'ok', text: 'No session with other hooks seen since this one started.' },
  )
  items.push(
    droppedForPrices > 0
      ? {
          label: 'Price table',
          state: 'fail',
          text:
            `${droppedForPrices} stored window${droppedForPrices === 1 ? ' was' : 's were'} dropped, priced with another table: ` +
            'another session runs a different usage-cost.mjs, or the table was just updated.',
        }
      : { label: 'Price table', state: 'ok', text: 'Every stored reading is priced with this table.' },
  )
  items.push(readingsItem(outcomes))
  if (summary) items.push(breakdownItem(((await host.get(READINGS_KEY)) ?? {}) as StoredReadings, summary.subscription))

  const check = await runScript<CheckSummary>(host, ['--check-summary'], 120_000).catch(error => ({ out: undefined, error: String(error) }))
  const unpriced = (summary?.windows ?? []).filter(s => s.isUnpriced).map(s => s.title)
  items.push(
    pricesItem(check.out ?? { sessions: 0, medianRatio: null, lowRatio: null, highRatio: null, error: check.error ?? 'no output' }, unpriced),
  )
  items.push({
    label: 'Other usage',
    state: 'info',
    text: 'Usage on other machines and on claude.ai is not counted and makes the allowance look smaller; an "inferred change" notice is the sign of it.',
  })
  return { type: 'check', items }
}

export function toCalibrationReport(summary: Summary): CalibrationReport {
  return {
    type: 'calibration',
    windows: summary.windows.map(s => {
      const c = s.calibration
      return {
        title: s.title,
        levels: c.levels,
        ticks: c.ticks,
        closedWindows: c.closedWindows,
        closedForWithin: c.closedForWithin,
        isWithinMeasured: c.isWithinMeasured,
        pastPoints: c.pastPoints,
        pastWeight: c.pastWeight,
        isBetweenMeasured: c.isBetweenMeasured,
        closedForRounding: c.closedForRounding,
        roundingNeeded: MIN_ROUNDING_WINDOWS,
        isRoundingKnown: c.isRoundingKnown,
        rounding: c.rounding,
        measured: c.measured,
        isCalibrated: c.isCalibrated,
        halfWidth: c.halfWidth,
      }
    }),
  }
}

/* "Fable 5.1" for claude-fable-5-1; a key of another shape as it is. */
function priceKeyLabel(priceKey: string) {
  const parts = /^claude-([a-z]+)-(\d+(?:-\d+)*)$/.exec(priceKey)
  const name = parts?.[1]
  const version = parts?.[2]
  return name && version ? `${name.charAt(0).toUpperCase()}${name.slice(1)} ${version.replace(/-/g, '.')}` : priceKey
}

function groupLabel(group: string) {
  if (group === 'all') return 'all models'
  if (group.endsWith('/read')) return `${priceKeyLabel(group.slice(0, -'/read'.length))} cache reads`
  if (group.endsWith('/other')) return `${priceKeyLabel(group.slice(0, -'/other'.length))} except cache reads`
  return priceKeyLabel(group)
}

function fitReport(f: FitResult): ModelsFit {
  const t = tQuantile(0.95, Math.max(1, f.df))
  return {
    model: f.model,
    reference: f.groups.reference,
    referenceLabel: groupLabel(f.groups.reference),
    groups: f.groups.free.map((key, g) => {
      const theta = f.theta[g] ?? 0
      const half = t * (f.se[g] ?? 0)
      return {
        key,
        label: groupLabel(key),
        weight: { value: Math.exp(theta), low: Math.exp(theta - half), high: Math.exp(theta + half) },
        information: f.information[g] ?? 0,
      }
    }),
    omega: f.omega,
    windows: f.windows,
    segments: f.segments,
    df: f.df,
  }
}

const EMPTY_SELECTION: Selection = {
  selected: 'M0',
  weights: UNIT_WEIGHTS,
  rounding: 'union',
  fits: {},
  comparisons: [],
  windows: { used: 0, excluded: {} },
  segments: 0,
  excludedSegments: 0,
}

const spreadOf = (s: { omega: number; windows: number; isAssumed: boolean }) => ({ omega: s.omega, windows: s.windows, isAssumed: s.isAssumed })

/** The meter-weight study: a forced measure, then the subscription's model fit, refitted
    when new windows qualify. */
export async function modelsReport(host: Host): Promise<ModelsReport> {
  const summary = await remeasure(host)
  await backfillSettled()
  const context = meterContext && (!summary || summary.subscription === meterContext.subscription) ? meterContext : undefined
  const entry = context
    ? await refreshMeter(host, context).catch(error => {
        host.log(`usage-dollars: model fit: ${String(error)}`)
        return undefined
      })
    : undefined
  const input = context ? await meterInputOf(host, context) : undefined
  const selection = entry?.selection ?? EMPTY_SELECTION
  const rounding = entry?.rounding ?? 'union'

  /* Closed 5-hour windows of the regime without complete features, live. */
  const incomplete = (input?.closed.five_hour ?? []).filter(({ w }) => !isFeatureComplete(w))
  const unverified = incomplete.filter(({ w }) => w.featuresUnverified).length
  const excluded = [
    { reason: 'dollars per model not stored yet', count: incomplete.length - unverified },
    { reason: 'dollars per model could not be rebuilt', count: unverified },
    { reason: 'fewer than 2 segments', count: selection.windows.excluded['too-few-segments'] ?? 0 },
  ].filter(e => e.count > 0)

  const omegas = input
    ? KINDS.map(kind => {
        const closed = (input.closed[kind] ?? []).map(({ w }) => w)
        const weights = entry?.fits[kind]?.weights ?? UNIT_WEIGHTS
        const views = closed.flatMap(w => weightedView(w, weights) ?? [])
        return {
          title: KIND_TITLES[kind],
          M0: spreadOf(calibrateOmega(closed, kind, input.now, input.resolution, rounding)),
          selected: spreadOf(calibrateOmega(views, kind, input.now, input.resolution, rounding)),
        }
      })
    : []

  const prospective = KINDS.map(kind => {
    const d = (entry?.prospective ?? []).filter(p => p.kind === kind).map(p => p.d)
    const n = d.length
    const sum = d.reduce((a, b) => a + b, 0)
    const variance = n > 1 ? d.reduce((a, b) => a + (b - sum / n) ** 2, 0) / (n - 1) : 0
    return { title: KIND_TITLES[kind], n, sum, se: Math.sqrt(n * variance) }
  })

  const transfer = entry?.transfer
  const models: readonly FitResult['model'][] = ['M0', 'M1', 'M2']
  return {
    type: 'models',
    isFitted: selection.fits.M0 !== undefined,
    qualifying: selection.windows.used,
    needed: FIT_MIN_WINDOWS,
    windows: { used: selection.windows.used, excluded },
    segments: selection.segments,
    excludedSegments: selection.excludedSegments,
    fits: models.flatMap(m => {
      const f = selection.fits[m]
      return f ? [fitReport(f)] : []
    }),
    comparisons: selection.comparisons.map(c => ({ ...c })),
    selected: selection.selected,
    rounding,
    transfer: {
      isChecked: transfer?.isChecked ?? false,
      isRejected: transfer?.isRejected ?? false,
      days: transfer?.days ?? 0,
      delta: transfer?.delta ?? 0,
      se: transfer?.se ?? 0,
      weeks: transfer?.weeks ?? 0,
      ...(transfer?.weeklyFit ? { weeklyFit: fitReport(transfer.weeklyFit) } : {}),
    },
    omegas,
    prospective,
  }
}

files.hooks/probe.ts:
/* The check message: a real turn sent from the first-reading card, only when the person
   presses its button, since only a main-conversation reply brings a usage reading in a
   headless session. Pure: register.tsx sends it and keeps the in-flight flag. */

import type { WaitingReport } from '../types'

/* Says what it is in the transcript, and keeps the turn as short as the session's model
   allows. Carries nothing from the session. */
export const CHECK_PROMPT =
  'usage-dollars check: this message only fetches a usage reading. Reply with the single word OK. Do not use any tools.'

export const CHECK_LABEL = 'Send a short check message (uses one turn)'

/** The first-reading card for `command`: a subscription with no check in flight may send
    one; a sign-in without a subscription never gets a reading to wait for. */
export function waitingReport(command: string, subscription: string, isCheckInFlight: boolean): WaitingReport {
  if (subscription === 'none') return { type: 'waiting', command, canSend: false, isUnsubscribed: true }
  return { type: 'waiting', command, canSend: !isCheckInFlight }
}

files.hooks/estimate.ts:
/* Estimates a rate-limit window's allowance in dollars from readings of (used dollars,
   reported percent) and gives a 90% range.

   Model, in natural logs. A is the dollars counted when the window reaches 100%, so the
   window runs at D = A / 100 dollars per percent. Between windows log A ~ N(mu, tau²).
   Within a window the cumulative rate U(s) / s read at share s differs from D with
   variance omega² · (1/s − 1/100): an average of s one-percent steps against the average
   of all 100, which vanishes as s → 100.

   A percent p reported at resolution r means the true share lies in an interval set by
   how the source rounds: [p − r/2, p + r/2) when it rounds, [p, p + r) when it truncates,
   and their union while that is not known. The newest level gives the evidence: where the
   level below it was also read, the tick was crossed between the two readings, at the
   lower edge of p's interval; otherwise anywhere in p's interval. Past windows give a
   prior on log A that the evidence is combined with by precision, unless the two
   contradict each other. tau and omega start from assumed values and are shrunk toward
   what closed windows show. */

import type { Confidence } from '../types'

/* minSlack and maxSlack: dollars of other sessions' requests close to that side's
   reading, which its percent may not include yet. minX and maxX: that side's dollars per
   feature, indexed by the window's features; a missing trailing index means 0. */
export type Bucket = {
  minUsd: number
  minAt: number
  maxUsd: number
  maxAt: number
  minSlack?: number
  maxSlack?: number
  minX?: number[]
  maxX?: number[]
}

/* pricesId: the price table the dollars were computed with. features: the feature keys
   of the buckets' minX and maxX, append-only. */
export type WindowReadings = { kind: string; resetsAt: string; byPct: Record<string, Bucket>; pricesId?: string; features?: string[] }

export type RangeEstimate = { value: number; low: number; high: number }

export type Rounding = 'round' | 'truncate' | 'union'

/** A past allowance in logs: a closed window's, at its reset, or a rejection's, at its time. */
export type PastPoint = { logA: number; variance: number; at: number }

/** A rate-limit rejection: the window was exactly full at `at`, with `usd` counted. */
export type Rejection = { kind: string; resetsAt: string; at: string; usd: number }

/** log A from one window's newest level `pct`, read at share `share`. shift: an error of
    up to that much either way, not random, from not knowing the rounding rule.
    crossingUsd: the dollars at the tick into that level, when it was seen. */
export type Evidence = { logA: number; variance: number; shift: number; share: number; pct: number; crossingUsd?: number }

/** The within-window spread omega, the age weight of the closed-window crossings behind
    it, and the number of closed windows that gave a crossing. It counts as measured from
    two windows on. */
export type Spread = { omega: number; weight: number; windows: number; isAssumed: boolean }

/** An allowance in logs: mean, variance, a non-random error of up to `shift` either way,
    and the degrees of freedom of the interval. */
export type LogEstimate = { mean: number; variance: number; shift: number; df: number }

export type Estimate = {
  allowance: RangeEstimate
  /** The log allowance behind `allowance`, before any extra variance. */
  log: LogEstimate
  left: RangeEstimate
  readings: number
  pastWindows: number
  pastWeight: number
  /** The between-window spread is the assumed one: under 3 effective past windows. */
  isSpreadAssumed: boolean
  /** No closed window has measured the within-window spread yet. */
  isWithinSpreadAssumed: boolean
  isPriorContradicted: boolean
  /** No level above 0 read in this window: the estimate is the prior alone. */
  isPriorOnly: boolean
  confidence: Confidence
  nextTick?: RangeEstimate
}

export type EstimateOptions = {
  resolution: number
  rounding: Rounding
  past: readonly PastPoint[]
  kind: string
  now: number
  livePercent?: number
  spread?: Spread
  /** Added to the log variance before the interval; 0 by default. */
  extraVariance?: number
}

const NU0 = 4
const TAU0 = 0.1
const OMEGA0 = 0.5
const REJECTION_SD = 0.02
const MIN_PAST_SHARE = 10
const MIN_CROSSING_SHARE = 5
const MIN_SPREAD_WINDOWS = 2
export const MIN_ROUNDING_WINDOWS = 5
const MINUTE_MS = 60 * 1000
const HOUR_MS = 60 * MINUTE_MS
const FIVE_HOUR_HALF_LIFE_MS = 24 * HOUR_MS
const SEVEN_DAY_HALF_LIFE_MS = 14 * 24 * HOUR_MS

export const ASSUMED_SPREAD: Spread = { omega: OMEGA0, weight: 0, windows: 0, isAssumed: true }

export function resolutionOf(all: readonly WindowReadings[]) {
  const isFine = all.some(w => Object.keys(w.byPct).some(p => !Number.isInteger(Number(p))))
  return isFine ? 0.1 : 1
}

const X_UNIT = 1e6

/* The window's features with x's new keys appended in sorted order. */
function featuresWith(features: readonly string[] | undefined, x: Record<string, number>) {
  const known = features ?? []
  const added = Object.keys(x)
    .filter(f => !known.includes(f))
    .sort()
  return [...known, ...added]
}

/* Within a window dollars only grow, so a tie keeps the later time: the most recent
   reading that still supports the bound. Each side keeps its reading's slack, and its
   per-feature dollars x, rounded to 1e-6, when the reading has them. */
export function record(w: WindowReadings, pct: number, usd: number, at: number, slack = 0, x?: Record<string, number>): WindowReadings {
  const key = String(pct)
  const was = w.byPct[key]
  const features = x ? featuresWith(w.features, x) : undefined
  const xs = x && features ? features.map(f => Math.round((x[f] ?? 0) * X_UNIT) / X_UNIT) : undefined
  let bucket: Bucket = { minUsd: usd, minAt: at, maxUsd: usd, maxAt: at, minSlack: slack, maxSlack: slack }
  let minX = xs
  let maxX = xs
  if (was) {
    const isMin = usd < was.minUsd || (usd === was.minUsd && at >= was.minAt)
    const isMax = usd > was.maxUsd || (usd === was.maxUsd && at >= was.maxAt)
    bucket = {
      minUsd: isMin ? usd : was.minUsd,
      minAt: isMin ? at : was.minAt,
      maxUsd: isMax ? usd : was.maxUsd,
      maxAt: isMax ? at : was.maxAt,
      minSlack: isMin ? slack : (was.minSlack ?? 0),
      maxSlack: isMax ? slack : (was.maxSlack ?? 0),
    }
    minX = isMin ? xs : was.minX
    maxX = isMax ? xs : was.maxX
  }
  if (minX) bucket.minX = minX
  if (maxX) bucket.maxX = maxX
  const byPct = { ...w.byPct, [key]: bucket }
  return features ? { ...w, features, byPct } : { ...w, byPct }
}

/* The window as seen from a regime that started at startedAt: readings taken before it
   are dropped. A straddling bucket keeps only its max side. */
export function regimeView(w: WindowReadings, startedAt: number): WindowReadings {
  const byPct: Record<string, Bucket> = {}
  for (const [key, b] of Object.entries(w.byPct)) {
    if (b.maxAt < startedAt) continue
    byPct[key] =
      b.minAt < startedAt
        ? {
            minUsd: b.maxUsd,
            minAt: b.maxAt,
            maxUsd: b.maxUsd,
            maxAt: b.maxAt,
            minSlack: b.maxSlack,
            maxSlack: b.maxSlack,
            ...(b.maxX ? { minX: b.maxX, maxX: b.maxX } : {}),
          }
        : b
  }
  return { ...w, byPct }
}

function shareOf(pct: number, resolution: number, rounding: Rounding) {
  if (rounding === 'round') return { lower: pct - resolution / 2, upper: pct + resolution / 2 }
  if (rounding === 'truncate') return { lower: pct, upper: pct + resolution }
  return { lower: pct - resolution / 2, upper: pct + resolution }
}

/* Where the share crosses into level p: one point, or for the union one of the two rules'
   points, taken at their geometric center with `shift`, half the log distance between
   them, as an error that is either rule's and not random. */
export function crossingShareOf(pct: number, resolution: number, rounding: Rounding) {
  if (rounding === 'round') return { s: pct - resolution / 2, variance: 0, shift: 0 }
  if (rounding === 'truncate') return { s: pct, variance: 0, shift: 0 }
  const lower = pct - resolution / 2
  return lower > 0
    ? { s: Math.sqrt(lower * pct), variance: 0, shift: Math.log(pct / lower) / 2 }
    : { s: pct - resolution / 4, variance: (resolution / 4) ** 2, shift: 0 }
}

/* A share uniform over a level's interval, never below 0. */
function levelShareOf(pct: number, resolution: number, rounding: Rounding) {
  const { lower, upper } = shareOf(pct, resolution, rounding)
  const from = Math.max(0, lower)
  return { s: (from + upper) / 2, variance: (upper - from) ** 2 / 12, shift: 0 }
}

export function bounds(w: WindowReadings, resolution: number, rounding: Rounding) {
  let low = 0
  let high = Infinity
  for (const [key, bucket] of Object.entries(w.byPct)) {
    const { lower, upper } = shareOf(Number(key), resolution, rounding)
    low = Math.max(low, bucket.maxUsd / (upper / 100))
    if (lower > 0) high = Math.min(high, bucket.minUsd / (lower / 100))
  }
  return { low, high }
}

export type Level = { pct: number; bucket: Bucket }

export const levelsOf = (w: WindowReadings): Level[] => Object.entries(w.byPct).map(([key, bucket]) => ({ pct: Number(key), bucket }))

/* The dollars at which the share crossed into `level`, when the level one step below was
   read before it: the midpoint of the gap less half the slack, uniform over the gap plus
   the slack. Keys of fine levels are not exact, hence the tolerance. */
export function crossingOf(levels: readonly Level[], level: Level, resolution: number) {
  const lower = levels.find(l => Math.abs(l.pct - (level.pct - resolution)) < resolution / 1000)
  if (!lower) return undefined
  const gap = level.bucket.minUsd - lower.bucket.maxUsd
  if (gap < 0) return undefined
  const slack = Math.max(level.bucket.minSlack ?? 0, lower.bucket.maxSlack ?? 0)
  return { usd: (lower.bucket.maxUsd + level.bucket.minUsd) / 2 - slack / 2, width: gap + slack }
}

/* Dollars uniform over usdWidth, the share at s with the given variance and shift. */
function evidenceAt(pct: number, usd: number, usdWidth: number, share: { s: number; variance: number; shift: number }, omega: number) {
  const { s } = share
  if (!(s > 0) || !(usd > 0)) return undefined
  const variance = share.variance / (s * s) + usdWidth ** 2 / (12 * usd * usd) + omega ** 2 * Math.max(0, 1 / s - 1 / 100)
  return { logA: Math.log((100 * usd) / s), variance, shift: share.shift, share: s, pct }
}

/** log A and its variance from the newest level of a window, the level with the latest
    reading. A level at or above 100 is used only through its crossing, since spending
    can continue past the limit; without one the next newest level is used. Level 0 is
    never used, since it bounds the share only from above. */
export function evidenceOf(w: WindowReadings, resolution: number, rounding: Rounding, omega = 0): Evidence | undefined {
  const levels = levelsOf(w)
  const newest = [...levels].sort((a, b) => b.bucket.maxAt - a.bucket.maxAt)
  for (const level of newest) {
    const crossing = crossingOf(levels, level, resolution)
    if (crossing) {
      const e = evidenceAt(level.pct, crossing.usd, crossing.width, crossingShareOf(level.pct, resolution, rounding), omega)
      return e && { ...e, crossingUsd: crossing.usd }
    }
    if (level.pct >= 100 || level.pct <= 0) continue
    const slack = level.bucket.maxSlack ?? 0
    return evidenceAt(level.pct, level.bucket.maxUsd - slack / 2, slack, levelShareOf(level.pct, resolution, rounding), omega)
  }
  return undefined
}

/** A closed window as a past allowance: its final evidence, with the within-window term
    of where it stopped, once it reached 10%. */
export function pastOf(w: WindowReadings, resolution: number, rounding: Rounding, omega: number): PastPoint | undefined {
  const e = evidenceOf(w, resolution, rounding, omega)
  if (!e || e.pct < MIN_PAST_SHARE) return undefined
  return { logA: e.logA, variance: e.variance + e.shift ** 2, at: Date.parse(w.resetsAt) }
}

const minuteOf = (iso: string) => Math.round(Date.parse(iso) / MINUTE_MS)

/** One past point per window of `kind`, keyed by its reset to the minute: a rejection
    wins over the window's own readings, the earliest rejection over later ones. */
export function pastPoints(
  closed: readonly WindowReadings[],
  rejections: readonly Rejection[],
  kind: string,
  resolution: number,
  rounding: Rounding,
  omega: number,
): PastPoint[] {
  const byWindow = new Map<number, PastPoint>()
  for (const w of closed) {
    if (w.kind !== kind) continue
    const p = pastOf(w, resolution, rounding, omega)
    if (p) byWindow.set(minuteOf(w.resetsAt), p)
  }
  const rejected = new Map<number, PastPoint>()
  for (const r of rejections) {
    if (r.kind !== kind || !(r.usd > 0)) continue
    const key = minuteOf(r.resetsAt)
    const at = Date.parse(r.at)
    const was = rejected.get(key)
    if (!was || at < was.at) rejected.set(key, { logA: Math.log(r.usd), variance: REJECTION_SD ** 2, at })
  }
  for (const [key, p] of rejected) byWindow.set(key, p)
  return [...byWindow.values()]
}

export function weightOf(kind: string, ageMs: number) {
  const halfLife = kind === 'seven_day' ? SEVEN_DAY_HALF_LIFE_MS : FIVE_HOUR_HALF_LIFE_MS
  return 0.5 ** (Math.max(0, ageMs) / halfLife)
}

/** The weighted mean of past log allowances; tau², their spread beyond their own
    measurement variance, shrunk toward the assumed TAU0 with NU0 degrees of freedom; and
    the predictive variance of the next window's log allowance. A point weighs by its age
    and by its information q = TAU0² / (TAU0² + v): one whose own variance v is large
    beside the assumed tau² says little about the allowance or about tau. */
export function prior(past: readonly PastPoint[], kind: string, now: number) {
  const points = past.map(p => {
    const q = TAU0 ** 2 / (TAU0 ** 2 + p.variance)
    return { x: p.logA, v: p.variance, q, w: weightOf(kind, now - p.at) * q }
  })
  let sw = 0
  let sw2 = 0
  let swx = 0
  let swq2 = 0
  for (const p of points) {
    sw += p.w
    sw2 += p.w * p.w
    swx += p.w * p.x
    swq2 += p.w * p.q * p.q
  }
  const nEff = sw2 > 0 ? (sw * sw) / sw2 : 0
  const mean = sw > 0 ? swx / sw : 0
  let raw = 0
  const denominator = sw > 0 ? sw - sw2 / sw : 0
  if (denominator > 0) {
    let ss = 0
    let noise = 0
    for (const p of points) {
      ss += p.w * (p.x - mean) ** 2
      noise += p.w * p.v * (1 - p.w / sw)
    }
    raw = (ss - noise) / denominator
  }
  const extra = sw > 0 ? Math.max(0, nEff - 1) * (swq2 / sw) : 0
  const tau2 = (NU0 * TAU0 ** 2 + extra * Math.max(0, raw)) / (NU0 + extra)
  let spread = 0
  for (const p of points) spread += p.w * p.w * (tau2 + p.v)
  const variance = sw > 0 ? tau2 + spread / (sw * sw) : Infinity
  return { nEff, mean, tau2, variance, df: NU0 + extra, isUsable: nEff >= 1, isSpreadAssumed: 1 + extra < 3, points: past.length }
}

/** omega from closed windows that reached 10%: each tick crossed at share s in
    [5, sEnd/2] gives e = log(U/s) − log(U_end/sEnd), with E[e²] = omega² · (1/s − 1/sEnd).
    Age-weighted, and shrunk toward OMEGA0 with the weight of NU0 crossings. */
export function calibrateOmega(
  closed: readonly WindowReadings[],
  kind: string,
  now: number,
  resolution: number,
  rounding: Rounding,
): Spread {
  let sum = 0
  let weight = 0
  let windows = 0
  for (const w of closed) {
    const end = evidenceOf(w, resolution, rounding)
    if (!end || end.pct < MIN_PAST_SHARE) continue
    const age = weightOf(kind, now - Date.parse(w.resetsAt))
    const levels = levelsOf(w)
    let isCounted = false
    for (const level of levels) {
      const crossing = crossingOf(levels, level, resolution)
      if (!crossing || !(crossing.usd > 0)) continue
      const { s } = crossingShareOf(level.pct, resolution, rounding)
      if (s < MIN_CROSSING_SHARE || s > end.share / 2) continue
      const e = Math.log(crossing.usd / s) - (end.logA - Math.log(100))
      sum += (age * e * e) / (1 / s - 1 / end.share)
      weight += age
      isCounted = true
    }
    if (isCounted) windows++
  }
  return { omega: Math.sqrt((NU0 * OMEGA0 ** 2 + sum) / (NU0 + weight)), weight, windows, isAssumed: windows < MIN_SPREAD_WINDOWS }
}

/** Student's t quantile by the Cornish-Fisher expansion in 1/df to third order. */
export function tQuantile(p: number, df: number) {
  const z = normalQuantile(p)
  const z3 = z ** 3
  const z5 = z ** 5
  const z7 = z ** 7
  const g1 = (z3 + z) / 4
  const g2 = (5 * z5 + 16 * z3 + 3 * z) / 96
  const g3 = (3 * z7 + 19 * z5 + 17 * z3 - 15 * z) / 384
  return z + g1 / df + g2 / df ** 2 + g3 / df ** 3
}

/* Acklam's rational approximation; relative error under 1.2e-9. */
function normalQuantile(p: number) {
  const a = [-39.69683028665376, 220.9460984245205, -275.9285104469687, 138.357751867269, -30.66479806614716, 2.506628277459239]
  const b = [-54.47609879822406, 161.5858368580409, -155.6989798598866, 66.80131188771972, -13.28068155288572]
  const c = [-0.007784894002430293, -0.3223964580411365, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783]
  const d = [0.007784695709041462, 0.3224671290700398, 2.445134137142996, 3.754408661907416]
  const tail = (q: number) =>
    (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  if (p < 0.02425) return tail(Math.sqrt(-2 * Math.log(p)))
  if (p > 1 - 0.02425) return -tail(Math.sqrt(-2 * Math.log(1 - p)))
  const q = p - 0.5
  const r = q * q
  return (
    ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) /
    (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
  )
}

/* Which rounding the API uses, from closed windows of every subscription: a mode
   contradicted in at most 10% of at least 5 windows while the other is contradicted in at
   least half of them. The caller leaves out windows that straddle a regime start; a
   window that is inconsistent even under the union is ignored here. */
export function roundingEvidence(windows: readonly WindowReadings[], resolution: number) {
  /* A reading exactly on a boundary makes low equal high, up to floating-point noise. */
  const isEmpty = (b: { low: number; high: number }) => b.low > b.high * (1 + 1e-9)
  let considered = 0
  let roundConflicts = 0
  let truncateConflicts = 0
  for (const w of windows) {
    if (Object.keys(w.byPct).length < 3) continue
    const union = bounds(w, resolution, 'union')
    if (isEmpty(union)) continue
    considered++
    const round = bounds(w, resolution, 'round')
    const truncate = bounds(w, resolution, 'truncate')
    if (isEmpty(round)) roundConflicts++
    if (isEmpty(truncate)) truncateConflicts++
  }
  let rule: Rounding = 'union'
  if (considered >= MIN_ROUNDING_WINDOWS) {
    if (roundConflicts <= 0.1 * considered && truncateConflicts >= 0.5 * considered) rule = 'round'
    else if (truncateConflicts <= 0.1 * considered && roundConflicts >= 0.5 * considered) rule = 'truncate'
  }
  return { considered, roundConflicts, truncateConflicts, rule }
}

export function inferRounding(windows: readonly WindowReadings[], resolution: number): Rounding {
  return roundingEvidence(windows, resolution).rule
}

/** What has been measured for one window: the current window's levels and ticks, and
    whether each of the within-window spread, the between-window spread and the rounding
    rule rests on closed windows rather than on an assumption. */
export function calibrationOf(input: {
  current?: WindowReadings
  resolution: number
  spread: Spread
  prior: ReturnType<typeof prior>
  rounding: ReturnType<typeof roundingEvidence>
}) {
  const levels = input.current ? levelsOf(input.current) : []
  const ticks = levels.filter(level => crossingOf(levels, level, input.resolution) !== undefined).length
  const isWithinMeasured = !input.spread.isAssumed
  const isBetweenMeasured = !input.prior.isSpreadAssumed
  const isRoundingKnown = input.rounding.rule !== 'union'
  const measured = [isWithinMeasured, isBetweenMeasured, isRoundingKnown].filter(Boolean).length
  return {
    levels: levels.length,
    ticks,
    closedForWithin: input.spread.windows,
    isWithinMeasured,
    pastPoints: input.prior.points,
    pastWeight: Math.round(input.prior.nEff * 10) / 10,
    isBetweenMeasured,
    closedForRounding: input.rounding.considered,
    isRoundingKnown,
    measured,
    isCalibrated: measured === 3,
  }
}

export type Calibration = ReturnType<typeof calibrationOf>

export function confidenceOf(r: RangeEstimate): Confidence {
  const h = Math.sqrt(r.high / r.low) - 1
  return h <= 0.1 ? 'good' : h <= 0.3 ? 'fair' : 'rough'
}

/* The spend until the reported percent next moves: one tick's dollars less what was spent
   since the crossing into the current level, or without a crossing, up to one tick. */
function nextTickOf(a: RangeEstimate, usedUsd: number, resolution: number, crossingUsd: number | undefined) {
  const tick = (allowance: number) => (allowance / 100) * resolution
  if (crossingUsd === undefined) return { value: tick(a.value) / 2, low: 0, high: tick(a.high) }
  const at = (allowance: number) => Math.max(0, tick(allowance) - (usedUsd - crossingUsd))
  return { value: at(a.value), low: at(a.low), high: at(a.high) }
}

/** The 90% range of exp(mean), with extraVariance added to the log variance, and no
    value below floor. The union of the intervals either rounding rule gives. */
export function rangeOf(log: LogEstimate, extraVariance: number, floor: number): RangeEstimate {
  const { mean: m, shift, df } = log
  const h = tQuantile(0.95, df) * Math.sqrt(log.variance + extraVariance) + shift
  return {
    value: Math.max(floor, Math.exp(m)),
    low: Math.max(floor, Math.exp(m - h)),
    high: Math.max(floor, Math.exp(m + h)),
  }
}

export function estimate(w: WindowReadings, usedUsd: number, options: EstimateOptions): Estimate | undefined {
  const { resolution, rounding, past, kind, now, livePercent } = options
  const spread = options.spread ?? ASSUMED_SPREAD
  const ev = evidenceOf(w, resolution, rounding, spread.omega)
  const p = prior(past, kind, now)
  const isAtLimit = livePercent !== undefined && livePercent >= 100
  /* Only level 0 read: the prior alone stands in for the evidence. */
  const isUnticked = Object.keys(w.byPct).every(key => Number(key) <= 0)
  if (!ev && !(isUnticked && p.isUsable && !isAtLimit)) return undefined

  let m = ev ? ev.logA : p.mean
  let v = ev ? ev.variance : p.variance
  let shift = ev ? ev.shift : 0
  let df = ev ? NU0 + spread.weight : p.df
  let isPriorContradicted = false
  if (ev && p.isUsable && !isAtLimit) {
    const z = Math.max(0, Math.abs(ev.logA - p.mean) - ev.shift) / Math.sqrt(ev.variance + p.variance)
    isPriorContradicted = z > tQuantile(0.995, p.df)
    if (!isPriorContradicted) {
      v = 1 / (1 / p.variance + 1 / ev.variance)
      m = v * (p.mean / p.variance + ev.logA / ev.variance)
      shift = (ev.shift * v) / ev.variance
      df = p.df
    }
  }
  const log = { mean: m, variance: v, shift, df }
  const floor = isAtLimit ? 0 : usedUsd
  const allowance = rangeOf(log, options.extraVariance ?? 0, floor)
  const left = isAtLimit
    ? { value: 0, low: 0, high: 0 }
    : { value: allowance.value - usedUsd, low: allowance.low - usedUsd, high: allowance.high - usedUsd }
  const isLive = livePercent !== undefined && !isAtLimit
  const isSameLevel = ev !== undefined && livePercent !== undefined && Math.abs(ev.pct - livePercent) < resolution / 1000
  return {
    allowance,
    log,
    left,
    readings: Object.keys(w.byPct).length,
    pastWindows: p.points,
    pastWeight: Math.round(p.nEff * 10) / 10,
    isSpreadAssumed: p.isSpreadAssumed,
    isWithinSpreadAssumed: spread.isAssumed,
    isPriorContradicted,
    isPriorOnly: !ev,
    confidence: confidenceOf(allowance),
    nextTick: isLive ? nextTickOf(allowance, usedUsd, resolution, isSameLevel ? ev?.crossingUsd : undefined) : undefined,
  }
}

files.hooks/meter.ts:
/* Meter weights: whether the subscription meter counts each model's API dollars at the
   API price ratio, fitted on closed 5-hour windows.

   Per feature f (one priced token class of one model, or web searches) a window records
   its dollars X_f at both sides of every bucket. The meter is taken to count weighted
   dollars E = Σ w_f · X_f, with w_f = exp(θ_g) for f's group g and θ = 0 outside the free
   groups. Between two tick crossings at least SEG_MIN_SHARE points apart, a segment's
   y = log(w · ΔX / Δs) is its window's log dollars per percent, with variance ω² / Δs plus
   the crossings' own gaps. θ and ω are fitted with each window's level profiled out and a
   normal prior on θ; a blocked jackknife over windows gives θ's covariance. Models are
   chosen by blocked cross-validation, and the weekly windows test whether the 5-hour
   weights carry over to the week. */

import type { Bucket, Estimate, PastPoint, RangeEstimate, Rejection, Rounding, Spread, WindowReadings } from './estimate.ts'
import { calibrateOmega, crossingOf, crossingShareOf, estimate, levelsOf, pastPoints, rangeOf } from './estimate.ts'

/* Segments and the outlier rule (S3). */
const SEG_MIN_SHARE = 2
const OUTLIER_RATE = 0.1
/* Estimation (S4). */
const SIGMA_THETA = 0.5
const NM_TOLERANCE = 1e-6
const NM_MAX_ITERATIONS = 500
const OMEGA_START = 0.5
const MIN_GROUP_SHARE = 0.02
const MIN_WINDOWS = 4
const MIN_SEGMENTS = 2
/* Uncertainty and selection (S5, S6, S6b). */
const JACKKNIFE_BLOCKS = 20
const CV_FOLDS = 10
const SELECT_MIN_DELTA = 2
const SELECT_SE_MULTIPLE = 2
const SELECT_MIN_Z = 2
const TRANSFER_MIN_DAYS = 5
const GRADIENT_STEP = 0.01
const WEEKLY_FIT_MIN_WEEKS = 4
/* Feature-complete windows (S2). */
const FEATURE_TOLERANCE_RELATIVE = 1e-6
const FEATURE_TOLERANCE_ABSOLUTE = 2e-4
/* Nelder-Mead's initial step from the fixed start and from a warm start, and the simplex
   size within which it stops once the objective has converged. */
const NM_STEP = 0.25
const NM_WARM_STEP = 0.05
const NM_X_TOLERANCE = 1e-4
/* ω is searched within these bounds; noise-free data would drive it to 0. */
const OMEGA_MIN = 1e-4
const OMEGA_MAX = 10
/* Shares of fine levels are not exact. */
const SHARE_EPSILON = 1e-9
const MINUTE_MS = 60 * 1000
const DAY_MS = 24 * 60 * MINUTE_MS

const MODELS = ['M0', 'M1', 'M2'] as const

export type Model = 'M0' | 'M1' | 'M2'

/** The groups of one model. `reference` has θ = 0; `free` are the groups with a θ, in a
    fixed order (sorted by key). Any group not in `free` (the reference, merged groups,
    `web`, and groups never seen) has weight 1. */
export type Grouping = { model: Model; reference: string; free: string[] }

/** Grouping plus θ (aligned with `free`), the jackknife covariance Σ_J (free × free), and the
    jackknife degrees of freedom K − 1. JSON-serializable. */
export type Weights = Grouping & { theta: number[]; cov: number[][]; df: number }

export const UNIT_WEIGHTS: Weights = { model: 'M0', reference: 'all', free: [], theta: [], cov: [], df: 1 }

export type Segment = {
  /** ΔX by feature. */
  dX: Record<string, number>
  /** Δs, percentage points. */
  ds: number
  /** Per-feature gap at the start crossing: level min side less lower max side. */
  gapA: Record<string, number>
  /** The same at the end crossing. */
  gapB: Record<string, number>
  /** Time of the end crossing (ms). */
  at: number
  /** The outlier rule of S3, evaluated at θ = 0. */
  isExcluded: boolean
}

export type FitOptions = {
  resolution: number
  rounding: Rounding
  /** Fixed grouping: skips both pruning steps. */
  groups?: Grouping
  /** Default true. */
  isJackknifed?: boolean
}

export type FitResult = {
  model: Model
  groups: Grouping
  /** Aligned with groups.free. */
  theta: number[]
  omega: number
  /** Σ_J; zeros when not jackknifed. */
  cov: number[][]
  /** sqrt(diag Σ_J). */
  se: number[]
  /** K − 1 of the jackknife. */
  df: number
  /** I_g of S4, aligned with groups.free. */
  information: number[]
  /** Windows that entered the fit. */
  windows: number
  /** Non-excluded segments used. */
  segments: number
  excludedSegments: number
  weights: Weights
}

export type Comparison = { from: Model; to: Model; delta: number; se: number; folds: number; isSelected: boolean }

export type Selection = {
  selected: Model
  /** Of the selected model; UNIT_WEIGHTS for M0. */
  weights: Weights
  /** The rule it was run under. */
  rounding: Rounding
  fits: Partial<Record<Model, FitResult>>
  /** M1 against M0, then M2 against the selected model. */
  comparisons: Comparison[]
  /** Reasons: 'not-feature-complete', 'too-few-segments', 'not-five-hour'. */
  windows: { used: number; excluded: Record<string, number> }
  segments: number
  excludedSegments: number
}

export type Transfer = {
  /** days ≥ TRANSFER_MIN_DAYS. */
  isChecked: boolean
  /** isChecked and delta < −max(2, 2 · se). */
  isRejected: boolean
  delta: number
  se: number
  days: number
  /** Qualifying weekly windows. */
  weeks: number
  /** ω_week fitted with θ held fixed, per candidate. */
  omega: { selected: number; M0: number }
  /** Descriptive weekly-only M1 fit, from WEEKLY_FIT_MIN_WEEKS weeks. */
  weeklyFit?: FitResult
}

export type StoredFit = { weights: Weights; omega: number; omegaM0: number }

export type ProspectiveRecord = { resetsAt: string; kind: string; d: number }

export type WeightedEstimateInput = {
  kind: string
  /** Closed windows of this kind and regime, already regimeView'd. */
  closed: readonly WindowReadings[]
  /** Already regimeView'd. */
  current: WindowReadings | undefined
  /** U of the current window (the tally's usd). */
  usedUsd: number
  /** The current tally's byFeature. */
  usedX: Record<string, number>
  /** The last7d tally's byFeature, for w̄ when U = 0. */
  fallbackX?: Record<string, number>
  weights: Weights
  rejections: readonly Rejection[]
  resolution: number
  rounding: Rounding
  now: number
  livePercent?: number
  /** Past points before it are dropped. */
  startedAt: number
}

export type WeightedEstimate = {
  /** In weighted dollars E, with extraVariance applied. */
  estimate?: Estimate
  /** In U dollars at the window's mix: E-values / w̄. */
  display?: { allowance: RangeEstimate; left: RangeEstimate; nextTick?: RangeEstimate }
  usedE: number
  /** w̄_window. */
  mixWeight: number
  /** ∇ᵀ Σ_J ∇ added to the log variance. */
  extraVariance: number
  spread: Spread
  past: PastPoint[]
  /** Closed windows that could not be transformed. */
  excludedClosed: number
}

const sumOf = (xs: readonly number[]) => xs.reduce((a, b) => a + b, 0)

const zerosOf = (n: number) => new Array<number>(n).fill(0)

const zeroMatrixOf = (n: number) => Array.from({ length: n }, () => zerosOf(n))

const minuteOf = (iso: string) => Math.round(Date.parse(iso) / MINUTE_MS)

/* Σ_i x_i · w_i over x's length; a missing trailing index of x is 0. */
function dotOf(w: readonly number[], x: readonly number[] | undefined) {
  let s = 0
  if (x) for (let i = 0; i < x.length; i++) s += w[i] * x[i]
  return s
}

const quadraticOf = (g: readonly number[], m: readonly (readonly number[])[]) => {
  let s = 0
  for (let a = 0; a < g.length; a++) for (let b = 0; b < g.length; b++) s += g[a] * (m[a]?.[b] ?? 0) * g[b]
  return s
}

function sampleVarianceOf(xs: readonly number[]) {
  if (xs.length < 2) return 0
  const mean = sumOf(xs) / xs.length
  return xs.reduce((s, x) => s + (x - mean) ** 2, 0) / (xs.length - 1)
}

function medianOf(xs: readonly number[]) {
  const sorted = [...xs].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2
}

/* priceKey and class of a feature key `<priceKey>[+fast]/<class>`. */
function partsOf(feature: string) {
  const slash = feature.lastIndexOf('/')
  const head = slash < 0 ? feature : feature.slice(0, slash)
  const cls = slash < 0 ? '' : feature.slice(slash + 1)
  return { priceKey: head.endsWith('+fast') ? head.slice(0, -'+fast'.length) : head, cls }
}

/** Natural group of a feature: M0 → 'all'; M1 → priceKey (fast and normal together);
    M2 → `${priceKey}/read` for class read, `${priceKey}/other` otherwise; `web` → 'web'
    under every model. */
export function groupOf(model: Model, feature: string): string {
  if (feature === 'web') return 'web'
  if (model === 'M0') return 'all'
  const { priceKey, cls } = partsOf(feature)
  if (model === 'M1') return priceKey
  return `${priceKey}/${cls === 'read' ? 'read' : 'other'}`
}

/** Reference = group with the largest dollars (ties by key order; never 'web'; in M2 the
    largest non-read group). Free = every other group except 'web', minus groups holding
    under MIN_GROUP_SHARE of the total dollars, which merge into the reference. */
export function groupsOf(model: Model, dollarsByFeature: Record<string, number>): Grouping {
  if (model === 'M0') return { model, reference: 'all', free: [] }
  const byGroup = new Map<string, number>()
  let total = 0
  for (const [feature, usd] of Object.entries(dollarsByFeature)) {
    total += usd
    const g = groupOf(model, feature)
    if (g !== 'web') byGroup.set(g, (byGroup.get(g) ?? 0) + usd)
  }
  const keys = [...byGroup.keys()].sort()
  const dollarsOf = (g: string) => byGroup.get(g) ?? 0
  const largestOf = (gs: readonly string[]) => gs.reduce<string | undefined>((best, g) => (best === undefined || dollarsOf(g) > dollarsOf(best) ? g : best), undefined)
  const nonRead = model === 'M2' ? keys.filter(g => !g.endsWith('/read')) : keys
  const reference = largestOf(nonRead.length > 0 ? nonRead : keys) ?? 'all'
  const free = keys.filter(g => g !== reference && total > 0 && dollarsOf(g) >= MIN_GROUP_SHARE * total)
  return { model, reference, free }
}

export function weightsOf(groups: Grouping, theta: readonly number[], cov?: number[][], df?: number): Weights {
  return {
    model: groups.model,
    reference: groups.reference,
    free: [...groups.free],
    theta: [...theta],
    cov: cov ?? zeroMatrixOf(groups.free.length),
    df: df ?? 1,
  }
}

/** exp(θ_g) for the feature's group, or 1. */
export function featureWeight(weights: Weights, feature: string): number {
  const g = weights.free.indexOf(groupOf(weights.model, feature))
  return g < 0 ? 1 : Math.exp(weights.theta[g])
}

/** w̄ = (w · x) / Σ x; 1 when Σ x is not above 0. */
export function mixWeight(weights: Weights, x: Record<string, number>): number {
  let sum = 0
  let weighted = 0
  for (const [feature, usd] of Object.entries(x)) {
    sum += usd
    weighted += featureWeight(weights, feature) * usd
  }
  return sum > 0 ? weighted / sum : 1
}

const isUnit = (weights: Weights) => weights.theta.every(t => t === 0)

const toleranceOf = (usd: number) => Math.max(FEATURE_TOLERANCE_RELATIVE * Math.abs(usd), FEATURE_TOLERANCE_ABSOLUTE)

const isSideComplete = (x: readonly number[] | undefined, usd: number, size: number) =>
  x !== undefined && x.length <= size && Math.abs(sumOf(x) - usd) <= toleranceOf(usd)

/** Every bucket has minX and maxX, and each array's sum equals its side's dollars within
    max(1e-6 · usd, 2e-4). */
export function isFeatureComplete(w: WindowReadings): boolean {
  const size = w.features?.length ?? 0
  return Object.values(w.byPct).every(b => isSideComplete(b.minX, b.minUsd, size) && isSideComplete(b.maxX, b.maxUsd, size))
}

/* The window in weighted dollars, from its features alone. */
function transformed(w: WindowReadings, weights: Weights): WindowReadings {
  const wf = (w.features ?? []).map(f => featureWeight(weights, f))
  const byPct: Record<string, Bucket> = {}
  for (const [key, b] of Object.entries(w.byPct)) {
    const minUsd = dotOf(wf, b.minX)
    const maxUsd = dotOf(wf, b.maxX)
    const bucket: Bucket = { ...b, minUsd, maxUsd }
    if (b.minSlack !== undefined) bucket.minSlack = b.minSlack * (b.minUsd > 0 ? minUsd / b.minUsd : 1)
    if (b.maxSlack !== undefined) bucket.maxSlack = b.maxSlack * (b.maxUsd > 0 ? maxUsd / b.maxUsd : 1)
    byPct[key] = bucket
  }
  return { ...w, byPct }
}

/** The window in weighted dollars E: minUsd/maxUsd become w · X at that side, slack is
    scaled by that side's E / U (1 when U = 0). Returns `w` itself when every weight is 1;
    `undefined` when the window is not feature-complete and some weight is not 1. */
export function weightedView(w: WindowReadings, weights: Weights): WindowReadings | undefined {
  if (isUnit(weights)) return w
  return isFeatureComplete(w) ? transformed(w, weights) : undefined
}

type Crossing = { s: number; usd: number; x: number[]; gap: number[]; at: number }

const recordOf = (features: readonly string[], values: readonly number[]) => Object.fromEntries(features.map((f, i) => [f, values[i]]))

/** S3: crossings (gap ≥ 0, as crossingOf), then segments with SEG_MIN_SHARE = 2. A side
    without features counts as 0 dollars in every feature. */
export function segmentsOf(w: WindowReadings, resolution: number, rounding: Rounding): Segment[] {
  const features = w.features ?? []
  const sideOf = (x: readonly number[] | undefined) => features.map((_, i) => x?.[i] ?? 0)
  const levels = levelsOf(w)
  const crossings: Crossing[] = []
  for (const level of levels) {
    if (!crossingOf(levels, level, resolution)) continue
    const lower = levels.find(l => Math.abs(l.pct - (level.pct - resolution)) < resolution / 1000)
    if (!lower) continue
    const from = sideOf(lower.bucket.maxX)
    const to = sideOf(level.bucket.minX)
    crossings.push({
      s: crossingShareOf(level.pct, resolution, rounding).s,
      usd: (lower.bucket.maxUsd + level.bucket.minUsd) / 2,
      x: from.map((v, i) => (v + to[i]) / 2),
      gap: to.map((v, i) => v - from[i]),
      at: Math.max(level.bucket.minAt, lower.bucket.maxAt),
    })
  }
  crossings.sort((a, b) => a.s - b.s || a.at - b.at)
  const pairs: [Crossing, Crossing][] = []
  let anchor = crossings[0]
  for (const c of crossings.slice(1)) {
    if (c.s - anchor.s < SEG_MIN_SHARE - SHARE_EPSILON) continue
    pairs.push([anchor, c])
    anchor = c
  }
  /* The rate at θ = 0 is in the window's own dollars U. */
  const rates = pairs.map(([a, b]) => (b.usd - a.usd) / (b.s - a.s))
  const median = rates.length > 0 ? medianOf(rates) : 0
  return pairs.map(([a, b], k) => ({
    dX: recordOf(features, b.x.map((v, i) => v - a.x[i])),
    ds: b.s - a.s,
    gapA: recordOf(features, a.gap),
    gapB: recordOf(features, b.gap),
    at: b.at,
    isExcluded: rates[k] < OUTLIER_RATE * median,
  }))
}

/* A window that qualifies for fitting: its usable segments, non-excluded with dollars, and
   how many the outlier rule excluded. */
type Prepared = { w: WindowReadings; usable: Segment[]; excluded: number }

/* Feature-complete windows with at least MIN_SEGMENTS usable segments, in resetsAt order. */
function qualify(windows: readonly WindowReadings[], resolution: number, rounding: Rounding) {
  const excluded: Record<string, number> = { 'not-feature-complete': 0, 'too-few-segments': 0 }
  const included: Prepared[] = []
  let segments = 0
  let excludedSegments = 0
  for (const w of windows) {
    if (!isFeatureComplete(w)) {
      excluded['not-feature-complete']++
      continue
    }
    const all = segmentsOf(w, resolution, rounding)
    const usable = all.filter(s => !s.isExcluded && sumOf(Object.values(s.dX)) > 0)
    if (usable.length < MIN_SEGMENTS) {
      excluded['too-few-segments']++
      continue
    }
    const out = all.filter(s => s.isExcluded).length
    included.push({ w, usable, excluded: out })
    segments += usable.length
    excludedSegments += out
  }
  included.sort((a, b) => Date.parse(a.w.resetsAt) - Date.parse(b.w.resetsAt))
  return { included, excluded, segments, excludedSegments }
}

function dollarsOf(prepared: readonly Prepared[]) {
  const dollars: Record<string, number> = {}
  for (const p of prepared) for (const s of p.usable) for (const [f, v] of Object.entries(s.dX)) dollars[f] = (dollars[f] ?? 0) + v
  return dollars
}

/* One window's usable segments summed by group: slot 0 holds every group of weight 1, slot
   g + 1 the free group g. offset centers y for precision; it cancels with α̂. */
type WindowColumns = {
  size: number
  offset: number
  logDs: number[]
  invDs: number[]
  dx: number[]
  ga: number[]
  gb: number[]
  at: number[]
}

type Columns = { n: number; windows: WindowColumns[] }

function columnsOf(prepared: readonly Prepared[], groups: Grouping): Columns {
  const n = groups.free.length
  const width = n + 1
  const slots = new Map<string, number>()
  const slotOf = (feature: string) => {
    let slot = slots.get(feature)
    if (slot === undefined) {
      slot = groups.free.indexOf(groupOf(groups.model, feature)) + 1
      slots.set(feature, slot)
    }
    return slot
  }
  const windows = prepared.map(p => {
    const size = p.usable.length
    const dx = zerosOf(size * width)
    const ga = zerosOf(size * width)
    const gb = zerosOf(size * width)
    p.usable.forEach((s, k) => {
      for (const [f, v] of Object.entries(s.dX)) dx[k * width + slotOf(f)] += v
      for (const [f, v] of Object.entries(s.gapA)) ga[k * width + slotOf(f)] += v
      for (const [f, v] of Object.entries(s.gapB)) gb[k * width + slotOf(f)] += v
    })
    const first = p.usable[0]
    return {
      size,
      offset: Math.log(sumOf(Object.values(first.dX)) / first.ds),
      logDs: p.usable.map(s => Math.log(s.ds)),
      invDs: p.usable.map(s => 1 / s.ds),
      dx,
      ga,
      gb,
      at: p.usable.map(s => s.at),
    }
  })
  return { n, windows }
}

const withoutBlock = (cols: Columns, [from, to]: readonly [number, number]): Columns => ({
  n: cols.n,
  windows: cols.windows.filter((_, i) => i < from || i >= to),
})

/* K contiguous blocks of `count` items, as [from, to) ranges. */
const blocksOf = (count: number, k: number) =>
  Array.from({ length: k }, (_, b) => [Math.floor((b * count) / k), Math.floor(((b + 1) * count) / k)] as [number, number])

const logOmegaOf = (x: number) => Math.min(Math.log(OMEGA_MAX), Math.max(Math.log(OMEGA_MIN), x))

const omegaOf = (x: number) => Math.exp(logOmegaOf(x))

const expOf = (theta: readonly number[]) => [1, ...theta.map(t => Math.exp(t))]

/* ½ Σ_i Σ_k [(y_ik − α̂_i)² / V_ik + log V_ik], α̂_i the precision-weighted mean of window
   i's y; Infinity where some w · ΔX is not above 0. */
function devianceOf(cols: Columns, theta: readonly number[], logOmega: number) {
  const width = cols.n + 1
  const e = expOf(theta)
  const omega2 = omegaOf(logOmega) ** 2
  let total = 0
  for (const c of cols.windows) {
    let s0 = 0
    let s1 = 0
    let s2 = 0
    let sl = 0
    for (let k = 0; k < c.size; k++) {
      const base = k * width
      let dot = 0
      let a = 0
      let b = 0
      for (let j = 0; j < width; j++) {
        dot += e[j] * c.dx[base + j]
        a += e[j] * c.ga[base + j]
        b += e[j] * c.gb[base + j]
      }
      if (!(dot > 0)) return Infinity
      const y = Math.log(dot) - c.logDs[k] - c.offset
      const v = omega2 * c.invDs[k] + (a * a + b * b) / (12 * dot * dot)
      const p = 1 / v
      s0 += p
      s1 += p * y
      s2 += p * y * y
      sl += Math.log(v)
    }
    total += s2 - (s1 * s1) / s0 + sl
  }
  return total / 2
}

const penaltyOf = (theta: readonly number[]) => theta.reduce((s, t) => s + (t * t) / (2 * SIGMA_THETA ** 2), 0)

/* Each segment's w · ΔX, y less the window's offset, and V; a segment whose w · ΔX is not
   above 0 has V = Infinity, which leaves it out. */
function responsesOf(c: WindowColumns, e: readonly number[], omega: number) {
  const width = e.length
  const dots: number[] = []
  const ys: number[] = []
  const vs: number[] = []
  for (let k = 0; k < c.size; k++) {
    const base = k * width
    let dot = 0
    let a = 0
    let b = 0
    for (let j = 0; j < width; j++) {
      dot += e[j] * c.dx[base + j]
      a += e[j] * c.ga[base + j]
      b += e[j] * c.gb[base + j]
    }
    const isUsable = dot > 0
    dots.push(dot)
    ys.push(isUsable ? Math.log(dot) - c.logDs[k] - c.offset : 0)
    vs.push(isUsable ? omega * omega * c.invDs[k] + (a * a + b * b) / (12 * dot * dot) : Infinity)
  }
  return { dots, ys, vs }
}

/* log N(y_k; α̂, V_k) of each segment of one window, α̂ profiled; 0 for a segment left out. */
function densitiesOf(c: WindowColumns, theta: readonly number[], omega: number) {
  const { ys, vs } = responsesOf(c, expOf(theta), omega)
  let sp = 0
  let spy = 0
  ys.forEach((y, k) => {
    sp += 1 / vs[k]
    spy += y / vs[k]
  })
  const alpha = sp > 0 ? spy / sp : 0
  return ys.map((y, k) => (Number.isFinite(vs[k]) ? -0.5 * (Math.log(2 * Math.PI * vs[k]) + (y - alpha) ** 2 / vs[k]) : 0))
}

/* I_g = Σ (d_ik − d̄_i)² / V_ik: d_ik is group g's share of the segment's w · ΔX, d̄_i its
   precision-weighted window mean. */
function informationOf(cols: Columns, theta: readonly number[], omega: number) {
  const n = cols.n
  const width = n + 1
  const e = expOf(theta)
  const information = zerosOf(n)
  for (const c of cols.windows) {
    const { dots, vs } = responsesOf(c, e, omega)
    const sp = vs.reduce((s, v) => s + 1 / v, 0)
    if (!(sp > 0)) continue
    for (let g = 0; g < n; g++) {
      const shares = dots.map((dot, k) => (dot > 0 ? (e[g + 1] * c.dx[k * width + g + 1]) / dot : 0))
      const mean = shares.reduce((s, d, k) => s + d / vs[k], 0) / sp
      information[g] += shares.reduce((s, d, k) => s + (d - mean) ** 2 / vs[k], 0)
    }
  }
  return information
}

/* Minimizes f from `start` with a simplex of `step` along each axis, with the standard
   coefficients. Stops when the simplex's values lie within NM_TOLERANCE and its points
   within NM_X_TOLERANCE of the best, or after NM_MAX_ITERATIONS. */
function nelderMead(f: (x: number[]) => number, start: readonly number[], step: number): number[] {
  const d = start.length
  const valueOf = (x: number[]) => {
    const v = f(x)
    return Number.isNaN(v) ? Infinity : v
  }
  let points = [start.slice(), ...start.map((_, i) => start.map((v, j) => (i === j ? v + step : v)))]
  let values = points.map(valueOf)
  const order = () => {
    const index = points.map((_, i) => i).sort((a, b) => (values[a] < values[b] ? -1 : values[a] > values[b] ? 1 : a - b))
    points = index.map(i => points[i])
    values = index.map(i => values[i])
  }
  const replace = (x: number[], v: number) => {
    points[d] = x
    values[d] = v
  }
  for (let iteration = 0; iteration < NM_MAX_ITERATIONS; iteration++) {
    order()
    let size = 0
    for (const p of points) for (let i = 0; i < d; i++) size = Math.max(size, Math.abs(p[i] - points[0][i]))
    if (values[d] - values[0] <= NM_TOLERANCE && size <= NM_X_TOLERANCE) break
    const centroid = start.map((_, i) => {
      let s = 0
      for (let j = 0; j < d; j++) s += points[j][i]
      return s / d
    })
    const toward = (t: number) => centroid.map((c, i) => c + t * (points[d][i] - c))
    const reflected = toward(-1)
    const fr = valueOf(reflected)
    if (fr < values[0]) {
      const expanded = toward(-2)
      const fe = valueOf(expanded)
      if (fe < fr) replace(expanded, fe)
      else replace(reflected, fr)
    } else if (fr < values[d - 1]) {
      replace(reflected, fr)
    } else {
      const isOutside = fr < values[d]
      const contracted = toward(isOutside ? -0.5 : 0.5)
      const fc = valueOf(contracted)
      if (isOutside ? fc <= fr : fc < values[d]) replace(contracted, fc)
      else
        for (let j = 1; j <= d; j++) {
          points[j] = points[j].map((v, i) => points[0][i] + (v - points[0][i]) / 2)
          values[j] = valueOf(points[j])
        }
    }
  }
  order()
  return points[0]
}

const startOf = (n: number) => [...zerosOf(n), Math.log(OMEGA_START)]

/* (θ, log ω) minimizing the penalized objective Q of S4. */
function optimize(cols: Columns, start: readonly number[], step: number) {
  const n = cols.n
  return nelderMead(x => {
    const theta = x.slice(0, n)
    return devianceOf(cols, theta, x[n]) + penaltyOf(theta)
  }, start, step)
}

/* ω with θ held fixed. */
function omegaFitOf(cols: Columns, theta: readonly number[]) {
  if (cols.windows.length === 0) return OMEGA_START
  return omegaOf(nelderMead(x => devianceOf(cols, theta, x[0]), [Math.log(OMEGA_START)], NM_STEP)[0])
}

/* S5 on prepared columns: K = min(G, JACKKNIFE_BLOCKS) contiguous blocks, each left out in
   turn, refitting from x. */
function jackknifeOf(cols: Columns, x: readonly number[]) {
  const n = cols.n
  const k = Math.min(cols.windows.length, JACKKNIFE_BLOCKS)
  const df = Math.max(0, k - 1)
  if (n === 0 || k < 2) return { cov: zeroMatrixOf(n), se: zerosOf(n), df }
  const thetas = blocksOf(cols.windows.length, k).map(block => optimize(withoutBlock(cols, block), x, NM_WARM_STEP).slice(0, n))
  const mean = zerosOf(n).map((_, g) => sumOf(thetas.map(t => t[g])) / k)
  const cov = zeroMatrixOf(n).map((row, a) => row.map((_, b) => ((k - 1) / k) * sumOf(thetas.map(t => (t[a] - mean[a]) * (t[b] - mean[b])))))
  return { cov, se: cov.map((row, g) => Math.sqrt(row[g])), df }
}

type Fitted = { result: FitResult; cols: Columns; x: number[] }

/* S4 on qualifying windows, in resetsAt order. */
function fitPrepared(model: Model, prepared: readonly Prepared[], options: FitOptions): Fitted | undefined {
  if (prepared.length < MIN_WINDOWS) return undefined
  let groups = options.groups ?? groupsOf(model, dollarsOf(prepared))
  let cols = columnsOf(prepared, groups)
  let x = optimize(cols, startOf(groups.free.length), NM_STEP)
  if (!options.groups && groups.free.length > 0) {
    const information = informationOf(cols, x.slice(0, cols.n), omegaOf(x[cols.n]))
    const free = groups.free.filter((_, g) => information[g] >= 1 / SIGMA_THETA ** 2)
    if (free.length < groups.free.length) {
      groups = { ...groups, free }
      cols = columnsOf(prepared, groups)
      x = optimize(cols, startOf(free.length), NM_STEP)
    }
  }
  const n = cols.n
  const theta = x.slice(0, n)
  const omega = omegaOf(x[n])
  const k = Math.min(prepared.length, JACKKNIFE_BLOCKS)
  const jk = options.isJackknifed === false ? { cov: zeroMatrixOf(n), se: zerosOf(n), df: k - 1 } : jackknifeOf(cols, x)
  const result: FitResult = {
    model,
    groups: { model: groups.model, reference: groups.reference, free: [...groups.free] },
    theta,
    omega,
    cov: jk.cov,
    se: jk.se,
    df: jk.df,
    information: informationOf(cols, theta, omega),
    windows: prepared.length,
    segments: sumOf(prepared.map(p => p.usable.length)),
    excludedSegments: sumOf(prepared.map(p => p.excluded)),
    weights: weightsOf(groups, theta, jk.cov, jk.df),
  }
  return { result, cols, x }
}

/** S4. Throws if any window's kind is not 'five_hour'. Filters to feature-complete windows
    with ≥ 2 non-excluded segments; returns undefined below MIN_WINDOWS such windows. Group
    pruning (2% share, then information < 1/SIGMA_THETA²) unless `groups` is given; the
    dollars for the 2% rule are Σ ΔX over the non-excluded segments. */
export function fit(model: Model, windows: readonly WindowReadings[], options: FitOptions): FitResult | undefined {
  const other = windows.find(w => w.kind !== 'five_hour')
  if (other) throw new Error(`The meter weights are fitted on five_hour windows only, not ${other.kind}.`)
  return fitPrepared(model, qualify(windows, options.resolution, options.rounding).included, options)?.result
}

/** S5: blocked jackknife with K = min(G, 20) contiguous blocks in resetsAt order, refitting
    with the grouping held fixed, from θ and the ω fitted at it. */
export function jackknife(
  model: Model,
  windows: readonly WindowReadings[],
  groups: Grouping,
  theta: readonly number[],
  options: FitOptions,
): { cov: number[][]; se: number[]; df: number } {
  const cols = columnsOf(qualify(windows, options.resolution, options.rounding).included, { ...groups, model })
  return jackknifeOf(cols, [...theta, Math.log(omegaFitOf(cols, theta))])
}

/** Score of one window under fixed weights and ω: Σ_k log N(y_k; α̂, V_k), α̂ profiled as
    the precision-weighted mean. Undefined when the window is not feature-complete or has
    fewer than 2 usable segments. */
export function scoreWindow(w: WindowReadings, weights: Weights, omega: number, resolution: number, rounding: Rounding): number | undefined {
  const [prepared] = qualify([w], resolution, rounding).included
  if (!prepared) return undefined
  const [c] = columnsOf([prepared], weights).windows
  return sumOf(densitiesOf(c, weights.theta, omega))
}

/* Held-out score per fold: each fold's windows scored under the fit on the other folds. */
function crossValidated(fitted: Fitted, folds: readonly [number, number][]) {
  const { cols, x } = fitted
  const n = cols.n
  return folds.map(block => {
    const fx = optimize(withoutBlock(cols, block), x, NM_WARM_STEP)
    const theta = fx.slice(0, n)
    const omega = omegaOf(fx[n])
    let score = 0
    for (let i = block[0]; i < block[1]; i++) score += sumOf(densitiesOf(cols.windows[i], theta, omega))
    return score
  })
}

/** S6: blocked K-fold CV, K = min(G, 10), contiguous blocks; grouping held fixed per
    candidate (from its full fit). Rule: Δ > max(2, 2·SE_Δ), some |θ̂|/SE_J ≥ 2, ≥ 4 windows.
    Under 4 qualifying windows: selected 'M0' with no fits. */
export function selectModel(fiveHourWindows: readonly WindowReadings[], options: { resolution: number; rounding: Rounding }): Selection {
  const { resolution, rounding } = options
  const fiveHour = fiveHourWindows.filter(w => w.kind === 'five_hour')
  const q = qualify(fiveHour, resolution, rounding)
  const summary = {
    rounding,
    windows: { used: q.included.length, excluded: { ...q.excluded, 'not-five-hour': fiveHourWindows.length - fiveHour.length } },
    segments: q.segments,
    excludedSegments: q.excludedSegments,
  }
  const fitted: Partial<Record<Model, Fitted>> = {}
  const fits: Partial<Record<Model, FitResult>> = {}
  for (const model of MODELS) {
    const f = fitPrepared(model, q.included, { resolution, rounding })
    if (!f) continue
    fitted[model] = f
    fits[model] = f.result
  }
  if (!fitted.M0) return { selected: 'M0', weights: UNIT_WEIGHTS, fits, comparisons: [], ...summary }
  const folds = blocksOf(q.included.length, Math.min(q.included.length, CV_FOLDS))
  const scores = new Map<Model, number[]>()
  const scoresOf = (model: Model) => {
    let s = scores.get(model)
    if (!s) {
      s = crossValidated(fitted[model]!, folds)
      scores.set(model, s)
    }
    return s
  }
  const compare = (from: Model, to: Model): Comparison => {
    const target = fitted[to]?.result
    if (!target || !fitted[from] || target.groups.free.length === 0) return { from, to, delta: 0, se: 0, folds: 0, isSelected: false }
    const base = scoresOf(from)
    const d = scoresOf(to).map((s, k) => s - base[k])
    const delta = sumOf(d)
    const se = Math.sqrt(d.length * sampleVarianceOf(d))
    const isClear = target.theta.some((t, g) => target.se[g] > 0 && Math.abs(t) / target.se[g] >= SELECT_MIN_Z)
    return { from, to, delta, se, folds: d.length, isSelected: delta > Math.max(SELECT_MIN_DELTA, SELECT_SE_MULTIPLE * se) && isClear }
  }
  const first = compare('M0', 'M1')
  let selected: Model = first.isSelected ? 'M1' : 'M0'
  const second = compare(selected, 'M2')
  if (second.isSelected) selected = 'M2'
  const weights = selected === 'M0' ? UNIT_WEIGHTS : fits[selected]!.weights
  return { selected, weights, fits, comparisons: [first, second], ...summary }
}

/** S6b on qualifying weekly windows: ω_week fitted per candidate with θ held fixed, α
    profiled under each; d_day sums the segments' log-density differences by the UTC day of
    their end crossing. Under UNIT_WEIGHTS: unchecked, with both ω fitted under M0. */
export function transferCheck(weeklyWindows: readonly WindowReadings[], weights: Weights, options: { resolution: number; rounding: Rounding }): Transfer {
  const { resolution, rounding } = options
  const prepared = qualify(weeklyWindows, resolution, rounding).included
  const cols = columnsOf(prepared, weights)
  const zero = zerosOf(cols.n)
  const omegaM0 = omegaFitOf(cols, zero)
  const weeklyFit = prepared.length >= WEEKLY_FIT_MIN_WEEKS ? fitPrepared('M1', prepared, { resolution, rounding })?.result : undefined
  const reported = { weeks: prepared.length, ...(weeklyFit ? { weeklyFit } : {}) }
  if (isUnit(weights)) return { isChecked: false, isRejected: false, delta: 0, se: 0, days: 0, omega: { selected: omegaM0, M0: omegaM0 }, ...reported }
  const omega = omegaFitOf(cols, weights.theta)
  const byDay = new Map<number, number>()
  for (const c of cols.windows) {
    const selected = densitiesOf(c, weights.theta, omega)
    const plain = densitiesOf(c, zero, omegaM0)
    c.at.forEach((at, k) => {
      const day = Math.floor(at / DAY_MS)
      byDay.set(day, (byDay.get(day) ?? 0) + selected[k] - plain[k])
    })
  }
  const d = [...byDay.values()]
  const delta = sumOf(d)
  const se = Math.sqrt(d.length * sampleVarianceOf(d))
  const isChecked = d.length >= TRANSFER_MIN_DAYS
  return {
    isChecked,
    isRejected: isChecked && delta < -Math.max(SELECT_MIN_DELTA, SELECT_SE_MULTIPLE * se),
    delta,
    se,
    days: d.length,
    omega: { selected: omega, M0: omegaM0 },
    ...reported,
  }
}

/** S7: one record per new window that scores under both the stored weights and M0, with
    d = score_selected − score_M0; [] when the stored weights are M0's. */
export function prospectiveScore(
  stored: StoredFit,
  newWindows: readonly WindowReadings[],
  options: { resolution: number; rounding: Rounding },
): ProspectiveRecord[] {
  if (isUnit(stored.weights)) return []
  const records: ProspectiveRecord[] = []
  for (const w of newWindows) {
    const selected = scoreWindow(w, stored.weights, stored.omega, options.resolution, options.rounding)
    const plain = scoreWindow(w, UNIT_WEIGHTS, stored.omegaM0, options.resolution, options.rounding)
    if (selected === undefined || plain === undefined) continue
    records.push({ resetsAt: w.resetsAt, kind: w.kind, d: selected - plain })
  }
  return records
}

/** Deterministic string over the inputs listed in S7. Each window as (window key, bucket
    count, latest maxAt), sorted by key. */
export function fingerprintOf(input: {
  fiveHour: readonly { key: string; w: WindowReadings }[]
  weekly: readonly { key: string; w: WindowReadings }[]
  regimeStarts: Record<string, number>
  pricesId?: string
  schema: number
  stamp: number
}): string {
  const listOf = (windows: readonly { key: string; w: WindowReadings }[]) =>
    windows
      .map(({ key, w }) => {
        const buckets = Object.values(w.byPct)
        return [key, buckets.length, buckets.reduce((latest, b) => Math.max(latest, b.maxAt), 0)] as const
      })
      .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  return JSON.stringify({
    fiveHour: listOf(input.fiveHour),
    weekly: listOf(input.weekly),
    regimeStarts: Object.keys(input.regimeStarts)
      .sort()
      .map(key => [key, input.regimeStarts[key]]),
    pricesId: input.pricesId ?? null,
    schema: input.schema,
    stamp: input.stamp,
  })
}

/* Rejections in weighted dollars: each at the mix of the newest max side of the closed
   window with the same reset; dropped without that window or its features. */
function weightedRejections(closed: readonly WindowReadings[], rejections: readonly Rejection[], kind: string, weights: Weights) {
  const weighted: Rejection[] = []
  for (const r of rejections) {
    if (r.kind !== kind) continue
    const w = closed.find(c => c.kind === kind && minuteOf(c.resetsAt) === minuteOf(r.resetsAt))
    if (!w || !isFeatureComplete(w)) continue
    const newest = Object.values(w.byPct).reduce<Bucket | undefined>((a, b) => (!a || b.maxAt > a.maxAt ? b : a), undefined)
    if (!newest) continue
    const x = newest.maxX ?? []
    const total = sumOf(x)
    const wf = (w.features ?? []).map(f => featureWeight(weights, f))
    weighted.push({ ...r, usd: r.usd * (total > 0 ? dotOf(wf, x) / total : 1) })
  }
  return weighted
}

type Run = { estimate?: Estimate; view?: WindowReadings; spread: Spread; past: PastPoint[]; mix: number; usedE: number; excluded: number }

/* The pipeline in weighted dollars, through the features of every window. */
function runAt(input: WeightedEstimateInput, weights: Weights): Run {
  const { kind, closed, current, usedUsd, usedX, fallbackX, rejections, resolution, rounding, now, livePercent, startedAt } = input
  const views = closed.filter(w => isFeatureComplete(w)).map(w => transformed(w, weights))
  const view = current && isFeatureComplete(current) ? transformed(current, weights) : undefined
  const mix =
    usedUsd > 0 && sumOf(Object.values(usedX)) > 0
      ? mixWeight(weights, usedX)
      : fallbackX && sumOf(Object.values(fallbackX)) > 0
        ? mixWeight(weights, fallbackX)
        : 1
  const usedE = usedUsd * mix
  const spread = calibrateOmega(views, kind, now, resolution, rounding)
  const past = pastPoints(views, weightedRejections(closed, rejections, kind, weights), kind, resolution, rounding, spread.omega).filter(
    p => p.at >= startedAt,
  )
  const e = view ? estimate(view, usedE, { resolution, rounding, past, kind, now, livePercent, spread }) : undefined
  return { estimate: e, view, spread, past, mix, usedE, excluded: closed.length - views.length }
}

const scaledBy = (r: RangeEstimate, f: number): RangeEstimate => ({ value: r.value * f, low: r.low * f, high: r.high * f })

/** Weighted views of closed and current windows (closed ones that cannot be transformed are
    dropped and counted), calibrateOmega, pastPoints (under non-unit weights a rejection's
    usd is multiplied by the w̄ of the closed window with the same reset's newest max side
    when that window is feature-complete, otherwise the rejection is dropped), estimate().
    The displayed log quantity is L = e.log.mean − log w̄_window; its gradient by central
    finite differences of GRADIENT_STEP per free group through the whole pipeline gives
    extraVariance = ∇ᵀ Σ_J ∇, and estimate() is rerun with it. Under UNIT_WEIGHTS the result
    is the plain pipeline's; with a zero cov, the weighted pipeline's without extra variance.
    No estimate when the current window is not feature-complete under non-unit weights. */
export function weightedEstimate(input: WeightedEstimateInput): WeightedEstimate {
  const { kind, closed, current, usedUsd, weights, rejections, resolution, rounding, now, livePercent, startedAt } = input
  if (isUnit(weights)) {
    const spread = calibrateOmega(closed, kind, now, resolution, rounding)
    const past = pastPoints(closed, rejections, kind, resolution, rounding, spread.omega).filter(p => p.at >= startedAt)
    const e = current ? estimate(current, usedUsd, { resolution, rounding, past, kind, now, livePercent, spread }) : undefined
    return {
      estimate: e,
      display: e && { allowance: e.allowance, left: e.left, nextTick: e.nextTick },
      usedE: usedUsd,
      mixWeight: 1,
      extraVariance: 0,
      spread,
      past,
      excludedClosed: 0,
    }
  }
  const base = runAt(input, weights)
  let e = base.estimate
  let extraVariance = 0
  const isCovZero = weights.cov.every(row => row.every(v => v === 0))
  if (e && base.view && !isCovZero) {
    const displayedOf = (run: Run) => (run.estimate ? run.estimate.log.mean - Math.log(run.mix) : undefined)
    const at = (g: number, h: number) => displayedOf(runAt(input, { ...weights, theta: weights.theta.map((t, j) => (j === g ? t + h : t)) }))
    const l0 = e.log.mean - Math.log(base.mix)
    const gradient = weights.theta.map((_, g) => {
      const up = at(g, GRADIENT_STEP)
      const down = at(g, -GRADIENT_STEP)
      if (up !== undefined && down !== undefined) return (up - down) / (2 * GRADIENT_STEP)
      if (up !== undefined) return (up - l0) / GRADIENT_STEP
      if (down !== undefined) return (l0 - down) / GRADIENT_STEP
      return 0
    })
    extraVariance = quadraticOf(gradient, weights.cov)
    if (extraVariance > 0) {
      e = estimate(base.view, base.usedE, { resolution, rounding, past: base.past, kind, now, livePercent, spread: base.spread, extraVariance })
    }
  }
  const toU = 1 / base.mix
  return {
    estimate: e,
    display: e && { allowance: scaledBy(e.allowance, toU), left: scaledBy(e.left, toU), nextTick: e.nextTick && scaledBy(e.nextTick, toU) },
    usedE: base.usedE,
    mixWeight: base.mix,
    extraVariance,
    spread: base.spread,
    past: base.past,
    excludedClosed: base.excluded,
  }
}

/** Per priceKey in the tally: w̄_m = Σ_{f∈m} w_f x_f / Σ_{f∈m} x_f, with a 90% interval
    from ∂ log w̄_m / ∂θ_g (group g's share of model m's weighted dollars), Σ_J and
    t(0.95, df). `web` is not a model. */
export function modelConversion(weights: Weights, tally7d: Record<string, number>): Record<string, RangeEstimate> {
  const byModel = new Map<string, string[]>()
  for (const feature of Object.keys(tally7d).sort()) {
    if (feature === 'web') continue
    const { priceKey } = partsOf(feature)
    byModel.set(priceKey, [...(byModel.get(priceKey) ?? []), feature])
  }
  const n = weights.free.length
  const conversions: Record<string, RangeEstimate> = {}
  for (const [priceKey, features] of byModel) {
    let sum = 0
    let weighted = 0
    const byGroup = zerosOf(n)
    for (const feature of features) {
      const x = tally7d[feature]
      const wx = featureWeight(weights, feature) * x
      sum += x
      weighted += wx
      const g = weights.free.indexOf(groupOf(weights.model, feature))
      if (g >= 0) byGroup[g] += wx
    }
    const isPriced = sum > 0 && weighted > 0
    const gradient = isPriced ? byGroup.map(v => v / weighted) : zerosOf(n)
    const log = { mean: isPriced ? Math.log(weighted / sum) : 0, variance: quadraticOf(gradient, weights.cov), shift: 0, df: weights.df }
    conversions[priceKey] = rangeOf(log, 0, 0)
  }
  return conversions
}

